/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20051129-7","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"厚生委員会","time":"午前１０時０４分～午後２時２８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"最後に、順次、手続を拡大すると書いてあるんですけれども、こういった選定のポイントで、ほかにどんなものを考えられているんか尋ねました。","respondent":"谷田部健康課長","answer":"ざっと申し上げまして４００弱ございまして、今回モデル実施ということですから、問題なのは添付資料です。３７０事務ぐらい手続がありますので、どういうことが拡大できるか、これも検討していきたいと思ってあります。","id":"exchange-001"},{"speaker":"須藤委員","kind":"意見","question":"４００項目ぐらいある中で、できないものとあるんでしょうけれども、順次進めていくという考え方なんだろうと思うんです。どんなものがいくのかというのが、ちょっと気になったんで聞いたんですけれども、まだそこまでは入っていないということですねとの意見を述べました。","respondent":"谷田部健康課長","answer":"このモデル実施を踏まえまして、引き続き検討を行っていきたいということでありますけれども、犬の登録事項の変更というのは。成果を踏まえて、今後、順次拡大していきたいと考えています。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問・要望","question":"こういう手続があったら楽だという観点で、次を拡大していってもらわなきゃいけないと思うんで、どういうことがあるのかとお聞きしたんです。電子区役所というのが来ているんですから、そこを考えて次の拡大をお願いしたいということで、要望しておきます。","respondent":"谷田部健康課長","answer":"平成１６年８月に区長決定いたしました電子申請基本方針の取り組みの基本的な考え方ですけれども、まず１点目は、実際に使われる手続を。その後で、この利用者視点に加えて、業務の効率化を図っていくですので、私どもも、利用者の視点で、今回、１４手続のモデル実施を行うです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"かつ安全性がすごく求められると思うんですが、大きなところで結構なんですが、教えていただきたい。モデル実施が１月４日からなんですけれども、検討を加えていくのかという、スケジュール的なところを教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"これはどれぐらいのメンバーが集まってくるのかということを教えてください。２番目の「連携・強力」は、強力の「強」は違うと思うんですが、その辺はやっぱり訂正しておいてほしいと求めました。","respondent":"鶴見品川区保健所保健サービス課長","answer":"２の「強力」は誤字でございまして、ご指摘のとおりです。それから、企画財政課長、広報広聴課長、高齢福祉課長、障害者福祉課長、児童課長、保育課長、学務課長、対象部課長は以上です。","id":"exchange-005"},{"speaker":"須藤委員","kind":"意見","question":"それから、その次の緊急事態対策本部というのは、今度はどういうふうになるのか。いわゆる庁内の危機管理体制に準じて体制がつくられるのかどうか、そのあたりを聞かせてくださいとの意見を述べました。","respondent":"鶴見品川区保健所保健サービス課長","answer":"あるいは４Ａになりました場合には、区長が召集レベル２ということで、本部を立ち上げることになっております。この場合には、区長、助役、事業部長が全庁的に入るということになっております。","id":"exchange-006"},{"speaker":"川西委員","kind":"質問・要望","question":"うちの山村委員が質問したんですが、医学的に予防接種がどれだけ必要なのか、教えてほしいと求めました。それから、その年によって型が違うようですが、昨年、品川区内で死亡例というのは、実績でわかっていたら説明を求めました。","respondent":"鶴見品川区保健所保健サービス課長","answer":"乳幼児の予防接種率は約５０％と言われていまして、これは先進国を中心に行われている予防接種の中でも、特に一番高いほうと聞いております。","id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"それから、乳幼児が予防接種が必要かどうか、日本の中での医学界の考え方は、どういうふうに把握していらっしゃるのかということ。その危機を脱皮するために対策を立てられるんだと思いますが、どんなことをなさるんですか、伺います。","respondent":"鶴見品川区保健所保健サービス課長","answer":"特に小さいお子さんのいらっしゃるご家庭では、家族が受けられるということは、進められているところです。専門家の中には、発症予防に伴って、脳症の数も減るのではないかということで勧めている先生もいらっしゃいます。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、タミフルの種類なんかはどんなふうになっているのか、教えてほしいと求めました。当面、３,０００人分の備蓄ということなんですが、その保管方法、常温でいいのか、有効期間とか、その辺の薬について説明を求めました。","respondent":"鶴見品川区保健所保健サービス課長、谷田部健康課長","answer":"こちらのほうは吸入薬ということもありまして、あまり普及していないんですけれども、生産の増加は予定しているです。有効期限は５年ということで、粉末で備蓄している国もあるということで、そちらのほうは１０年と聞いております。いわゆるこの薬がなくなったという場合に、私ども区民の皆さん方の安全を確保するという観点で、３,０００人分を備蓄するということです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の新インフルエンザの特質というんですか、どういうタイプのものなのかということ、基本的なところを教えていただきたい。それから、対策の決め手というんですか、これからいろいろ手を打たれるんだと思いますけれども、その辺の基本的なところを、まずお願いいたします。","respondent":"鶴見品川区保健所保健サービス課長、青山品川区保健所長","answer":"Ｈ５の１にしても、Ｈ５Ｎ１がヒトインフルエンザになって、ヒトに対しても高い致死率を持つのではないかということが言われております。落ち着いて行動していくということが必要だと思いますし、適宜… あるいは感染しても発症しない方もあるというような状況を考えますと、それに感染すれば、即新型かもしれないということで対応がとれる。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一般的な、インフルエンザの予防接種のワクチンの量とかは大丈夫なんでしょうか。わかっている範囲で結構なので、その辺を教えてほしいと求めました。","respondent":"鶴見品川区保健所保健サービス課長、谷田部健康課長","answer":"インフルエンザワクチンにつきましては、今年度については、約２,０００万人分あるということで、現在のところは、特に足りなくなるといったことは聞いていない状況です。輸入販売元の製薬会社のほうでは、その辺の薬の確保というのは、非常に難しいような話は、薬剤師会にしているということは伺ってあります。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"心配なので、ちょっとその辺を教えていただきたい。外国人とか、そういった情報が入りにくい方への対応がどうなっているか、説明を求めました。","respondent":"鶴見品川区保健所保健サービス課長、谷田部健康課長、小林保育課長","answer":"残りについてははっきりわからず、今後検討が必要ということで、これから解明されていくところと思います。そういったことで、脳症のほうも… 説明しています健康危機管理対策基本指針に基づきまして、問題の重大性について認識し、適切な対応がとれるような方向で準備をしたいということと。… 保育園におきましては、看護師等もおりますので、庁内連絡会議と連携しながら、対応してまいります。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"全都で入院患者が２９万人とか、外来が３８０万人というような予想の数が出されていますけれども、とれるのかどうかということを１点お聞きしたい。そういうところの対策も、この対策連絡会議で、どういう方向にしていこうかという検討がされるということなんか尋ねました。","respondent":"鶴見品川区保健所保健サービス課長、青山品川区保健所長","answer":"委員のご指摘のとおり、この連絡会で、今後、院内感染を、少人数であれば出入口等の問題で、大人数であれば病院別とか、そういったことについて検討をしていく予定です。 今回はそこまでに言及する予定ではございませんが、各医療機関における役割を、それぞれ定めていきたいと考えています。再度点検していただくという方向を、現在、検討しています。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１２月２２日では、ぜひ、こういう対策会議の中でしっかりと練っていただきたいなと思っています。体力が落ちているというところでの対策ということで、既に考えられているようなことがあったら、ちょっと教えていただけますか尋ねました。","respondent":"鶴見品川区保健所保健サービス課長","answer":"ホームページのリンクのところに、施設内の対策についてのリンクのほうは、もう既に設けしています。３０歳代の方の致死率が高いということで、６０歳以上で亡くなられた方というのはほとんどないと聞いておりますけれども、参考につけ加えします。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区のタミフルの備蓄は３,０００人分とのことなんですけれども、なかなか確保が難しいというのが現実問題としてはあると思うんです。１５歳以下の方の死亡率が高いということから、おおむね１８歳以下を対象に備蓄ということで、ちょっと教えていただけますか尋ねました。","respondent":"谷田部健康課長","answer":"国内流通分を除く１,０５０万人、都道府県が１,０５０万人、その量で賄うべきだというのが基本的な考え方です。１９歳以上だからだめですよというわけにはまいりませんので、年齢に関係なく回さざるを得ないと思ってありますし、そうすべきだと思ってあります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"１点お伺いしたいと思っているのが、残っていた１３カ所すべてが閉鎖をする、一区切りがつけられるところなんです。安心して送り出せる状況に、向こう側のすまいるスクールがなっているという認識を持っていらっしゃるのか、改めてこの点をお伺いしたいと思います。","respondent":"辻田児童課長","answer":"特に小さなところで、２階にあったりいろいろな中で、結構施設整備も十分でない中でやっているというのが現状です。すまいるスクールの施設状況が悪いと言えるのか、私どものほうとしては、なかなか理解できないです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だからその点を、私は、一体どこで、どう把握をしてくれて、守ってくれるのかというところが、今の状況の中だと見えないんです。そういった面で、留守家庭の子どもたちの現状がどう把握されているのかというところを、お聞かせいただきたいんです。","respondent":"辻田児童課長","answer":"区の組織というのはいろいろあって、いわゆる所管が違うところで、その事業をやっているようなこともあります。まず責任を持って対応していくことだと思うので、名簿等をつくって、きちっと管理しているという形で聞いております。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"１部屋半ぐらいしかないところに１００名想定しているとか、今のすまいるスクールのほうがいいですよって言いきれるのか、どうか。そこのところで、私はすごく疑問を感じているんですが、その辺の把握はいかがなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"小学校の１年生から３年生までは、どう過ごしているのかという部分の把握をしていかないと、子どもの事故が非常に多いですよね。ぜひ、この点を考えていただきたいんですが、いかがか尋ねました。","respondent":"辻田児童課長","answer":"現実的に私どものほうがやっていた事業で考えてみますと、学童保育クラブで過ごすことはないんだというようなお子さんもいらっしゃることは事実です。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どう感じて、どう過ごしているのかという子ども本人の意見、今まではあまりないんじゃないか。その場をつくってほしいのと、ぜひアンケートなどをしていただきたいんですが、いかがか尋ねました。","respondent":"辻田児童課長","answer":"そういう中で、子どもたちの問題を考えていくというようなことは、十分に可能かと思われます。それから、アンケートについては、実施する考えはございません。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"意見","question":"アンケートを実施する気はございませんって、調整会議とか、そういう組織が１１地区にできたというのは、大変嬉しいことだと思います。だから、頭からやる気はございませんと断るのではなく、ぜひ、ご検討をお願いして、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"川西委員","kind":"質問","question":"ですから、ご意見としてはわかるんですが、私の住んでいるところは、あまり問題が出てきていないと思います。教育委員会のほうのどこかに移るのか、ちょっと教えておいてください。","respondent":"辻田児童課長","answer":"廃止後ということで、検討する状況になってくると思います。私どものほうにまいりますので、私どものほうも、連携を持ってやっていきたい。","id":"exchange-022"},{"speaker":"川西委員","kind":"質問","question":"１点だけ、もらって、それはやっているんですよね。ちょっと伺います。","respondent":"辻田児童課長","answer":"東京都は、民間の学童保育クラブには補助金を出しているんですけれども、２３区部分につきましては、補助金という形では出ておりません。いわゆるこれが財調処理という形になっております。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の件なんですけれども、第２種社会福祉事業に届出をしていると思うんですが、それは財調の算定ということで出しているということなんでしょうか。そこをちょっと説明を求めました。","respondent":"辻田児童課長","answer":"それから、東京都のほうは、確かにきちっとした形での対応をしてくださいということで、要綱等も出しております。それが、ある意味では、財調等に関係してくるのか、どうかという状況です。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここの第２種社会福祉事業に届出をして、ぜひ言っていただきたいと思うんですけれども、それが１点。新たに開設するところでどうなっているかというところを、そこがどうなっているのか、ちょっと説明を求めました。","respondent":"辻田児童課長","answer":"最初に始めた平成１５年のときに、どこでもやりなさいと、これが現在の方針なんです。きちっとした形ですまいるスクールは実施されていると思いますので、その中で、むしろその中でお話ししていただきたいです。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それは、そういう実態があるという親からの声もたくさん届いていますので、そこの把握については、ぜひお伝えをほしいと求めました。専用室がなくて、そういうところも、ぜひ把握した上での移行としていただきたいということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろいろお話を伺っていると、所管が教育委員会になったからどうの、僕らが願っていた形にならないと思うんです。これは部長にもお願いしたいんですけれども、していただきたいと思うんですが、いかがか尋ねました。","respondent":"辻田児童課長","answer":"いろいろな形で一緒に考えて、連携して、協力していく。すまいるスクールとの連携の中で、いろいろ子どもたちをきちっと見ていくということを、今後も実施していきたいということあります。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問・要望","question":"そうしますと、来年度は全部なってきますよね。向うの所管だから、こういう数字をちゃんとつかんでいますというようなことができるぐらいの連携をとっていただきたいと、お願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"川西委員","kind":"質問","question":"ここ３年ぐらいの実績について、伺います。それから、５番目の応募資格がずっとこれなんですけれども、改正がされてこないという理由を説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"福祉的な観点で、高齢者の住宅を確保するということで制度がつくられて、進めてきたものです。そういうことで、基本的に、この要件については、従来のままでいいのではないかということで、こういう形で進めているものです。","id":"exchange-029"},{"speaker":"川西委員","kind":"質問","question":"このまま、１８０人の約１割、１８人が入るというような状況の中で、品川区は、もうこういう住宅をつくっていませんよね。これでよしと考えるのか、どうか、伺いたい。","respondent":"蓼沼高齢事業課長","answer":"１５人から２０人ぐらい入居されて、１０名前後の方が次年度に持ち越しをしているという状況の中で、当面はよろしいのではないか。当面は、この形でよろしいのではないかと考えています。","id":"exchange-030"},{"speaker":"川西委員","kind":"意見","question":"毎年１５人から１８人、２０人ぐらいまでの間でと見ていると、また別の機会に。終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"山路委員","kind":"質問","question":"そういう全体観に立って、２部屋、３部屋あるところは若いお子さんのいらっしゃる方に入っていただく。高齢者の方に移っていただくとか、こういう面も含めての改善というのを考えられないものか、どうか、お伺いいたします。","respondent":"蓼沼高齢事業課長","answer":"高齢者向けですとか、障害者向けとか、要件がそれぞれあると思います。ちょっと難しいのかなという気がいたしますけれども、担当のほうに、ご意見は伝えてまいりたいと思います。","id":"exchange-032"},{"speaker":"山路委員","kind":"質問","question":"そういう方を受け入れる応募の内容の改善をしますと、公営住宅もあきますでしょ、そうしたら若い人が入れるでしょという意味なんです。応募資格に、お一人でお住まいのこの条件に合う人に、高齢者住宅で受け入れますよというような項目を入れたらどうですかという意味なんですけれども。","respondent":"蓼沼高齢事業課長","answer":"その辺は、公営住宅の住宅政策との兼ね合いもあろうかと思います。まずは、そういった基本的に特定している目的に沿った形で、運営をしていくべきであろうと考えております。","id":"exchange-033"},{"speaker":"山路委員","kind":"質問・要望","question":"部屋が二つあったら、高齢者住宅に移りたい、かえって都営住宅に一人でいるのが怖いとかいう高齢者も何人かいらっしゃるんです。高齢者住宅に受け入れていただければ、若い人に公的住宅が譲れるというシステムから、もう１回検討をしていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"１点お伺いしたいんですが、どうか、その点をお伺いします。","respondent":"蓼沼高齢事業課長","answer":"今現在、家賃助成を継続して受けられている方は４０件あります。高齢者住宅、あるいはその他への転居がスムーズにいくように、この２年間で対応を図ってまいりたいと考えております。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"先ほどのご答弁の中にも、やっぱり年間１５件から２０件の空きという状況では、なかなか困難な状況であるなと思っています。住宅が増えたらいいなと願っているんですが、その点を１点、ご答弁を。","respondent":"蓼沼高齢事業課長","answer":"いろいろと宅建のほうも組織的に対応していただいていて、いかにオーナーに、高齢者の方々への理解を深めていただくかというようないろいろな支援。入居支援の充実も含めて、総合的に対応していきたいと考えています。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"家賃助成を受けている方が４０件で、平成１７年度と平成１８年度で、そこを一つ教えていただきたい。１７０人の方に、ぜひお願いしたいと思うんですけれども、そのこととあわせてお願いします。","respondent":"蓼沼高齢事業課長","answer":"空き家を希望された方の優先度、緊急度を含めて、総合的に勘案しながら対応を進めている状況です。あるいは、回数は限られますけれども、広報でもあっ旋の制度につきましてはＰＲをしています。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ずっと求めてきたわけですけれども、ずっと質問の中でも取り上げてきた問題ですので、ぜひよろしくお願いしたいと思います。皆さんの共通の思いになるんじゃないかと思いますので、ぜひ、高齢者住宅の増設ということのご検討を要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"支援費ができて２年経ってというところで、品川区内においての利用の状況がどのぐらい増えていたのか、まず教えていただきたい。その辺の、具体的に、今現在わかっているところをわかりやすく、利用料負担のところを教えてほしいと求めました。","respondent":"西島障害者福祉課長","answer":"それから、２点目の、支援費の現在の応能負担の基準ですが、これは口頭で説明するのはものすごく難しいということになっています。何回か説明を聞いたんですが、細かく分かれておりますので、そういうふうに応能負担になっているというふうにご理解をいただければと思います。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"利用料負担のところで、具体的にもうちょっと詳しく１割負担の中身がわかっているので、わかっている範囲のところは、きちんと。もうちょっと具体的に決まっている中身のところで、お答えをいただきたいと思うんですけれども、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"重度継続、住民税の所得割が２万円というのは、の方の場合は５,０００円。市町村民税の所得割が２０万円未満なら、上限は１万円というふうな軽減措置が図られているです。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとその辺の割合がわかったら、お知らせいただきたい。今まで、支援費制度のときに、無料でサービスを受けられていた方が、在宅、そして、施設の部分で何％いらっしゃったのか、この辺を説明を求めました。","respondent":"西島障害者福祉課長","answer":"国の説明では、現在、ホームヘルプサービス等に関しましては、約５％の人が負担していただいている。所得が若干高いということがありますので、それよりは、負担率は若干高いというふうに認識をしています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きょう、ご説明いただいた中身で、次々にお伺いしたいところがありますので、よろしくお願いいたします。そこの中身を、それぞれもうちょっとわかりやすくご説明をいただきたいと思うんですが。","respondent":"西島障害者福祉課長","answer":"支援費制度の維持がなかなか難しいということの中から、必要な租税を確保するための国民的理解を安いものにしていくんだというのが、国の考え方です。国２分の１、都４分の１、区４分の１というふうに変わってくるところです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補装具ってどういう部分までか、私は一番には車いすとか思い浮かべるわけですけれども、補装具の中身と、負担のところを教えてほしい。さっき言ったのは、介護給付のところ、訓練給付、ここの分け方もよくわからないんですが、この辺の中身もご説明もほしいと求めました。","respondent":"西島障害者福祉課長","answer":"就労意向支援にいく部分、就労継続支援にいく部分、こういうふうに分かれてくるんだろうと。地域での自立を目指すということ、あるいは就労促進を図るということで、事業単位に組みかえるというふうにご理解いただければと思います。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"電動車いすなんかは５０万円ぐらいすると聞いたので、今、伺っていました。どこがこれを担うのかというところを、ご説明いただきたいです。","respondent":"西島障害者福祉課長","answer":"相談支援事業者のお尋ねですが、これにつきましては、まだ明確になっておりません。相談支援事業者は現在ございませんので、相談支援事業者というのは、おそらく大多数は利用者本人がみずから申請するという形になろうと思います。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"ここの相談支援事業者の下に、「市町村がみずから相談支援を担う場合あり」と書いてあるんですが、これはじゃあ、利用者本人がするということですか。どこかに設けられるという意味ではないんか尋ねました。","respondent":"西島障害者福祉課長","answer":"「市町村がみずから相談支援を担う場合あり」ということで、ご本人と面談をして、ご要望をお聞きしてという形になる。将来はちょっと別といたしまして、当面、現行と変わらないというふうにご理解いただければと思います。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とりあえずの最後にしたいと思うんですが、ぜひ、相談支援事業者というのは、介護保険のように、ケアマネジャー、いろいろな障害の部分をよく理解した専門家をここに当てていただきたいと考えていますので、これは意見として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"須藤委員","kind":"質問","question":"それから、申請して利用できるまで、審査とかして、時間的にはどのぐらいかかっちゃうんですか。そのあたりがどういうふうに、例えば１週間後にどこかに出かけたいんでとか、もう少し詳しくこの辺のところを説明を求めました。","respondent":"西島障害者福祉課長","answer":"相談支援事業者の育成はなかなか困難かなということで、現在も対応していますし、それでしばらくは実施していきたい。ご要望があった場合には、できるだけ速やかに聞き取り調査をして、速やかに審査会をして、実施したい。","id":"exchange-047"},{"speaker":"須藤委員","kind":"質問","question":"できるだけ障害者の皆さんに迷惑をかけないように、省令がこなきゃ、委員がどうのっていことじゃないと思うんですよ。今までいろいろなことで利用されているわけですから、この規則にその人たちを合わせるのじゃなくて、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"１００％完璧なものというのはございませんけれども、いろいろな意見があるのは、確かに承知しております。国の動向はさておきまして、品川区として、従来のサービスをより充実させる方向で進めてまいりたいと考えているところです。","id":"exchange-048"},{"speaker":"川西委員","kind":"質問","question":"５番の基本指針に則して、障害福祉計画の流れを説明を求めました。","respondent":"西島障害者福祉課長","answer":"障害福祉計画については、障害福祉計画を平成１８年度中に策定するというところまでしか聞いてございませんで、ここに何を定め、何をというようなことにつきましては、これから国が指針を示すと、その指針に従って各都道府県、市区町村が平成１８年度中に定めると聞いてあります。","id":"exchange-049"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、就労の支援を含めた所得の確保ということで、今までは、地方自治体は、あまりそういうことにかかわっていなかったけれども、計画の中に盛り込まれて、近隣地域への就労ということにも関与することが入ってくるのか、どうか、伺います。","respondent":"西島障害者福祉課長","answer":"障害者の就労支援センターを平成１５年に立ち上げまして、２年間で４６名だと思いましたけれども、就労の確保に向けて取り組んでおります。２月に１回ですが、まさにこの取り組みをより充実をさせていくことが、この法律の理念にかなうものだと判断しています。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域生活支援事業の中身について、お伺いいたします。先日の一般質問で、今までどおり無料で行っていただきたいということで、利用の現況がどのぐらいになっているのかということをお伺いしたい。","respondent":"西島障害者福祉課長","answer":"４３１回、区役所にお見えになった方の手話通訳を実施していますが、それが９９回というふうになってあります。地域支援事業につきましては、これは１０月から実施される事業ですが、国のガイドラインを踏まえて検討してまいりたいと考えているところです。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きょう伺っても、わかりやすいパンフレットもつくって、説明会をしてほしいと求めました。二段構えでご説明をしていただきたいというのは、そのところは実現をしてほしいと求めましたが、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"大まかはっきりしてまいりましたので、障害者７団体、あるいは民生委員協議会等で説明をする予定になってあります。２月から３月にかけて、法の趣旨も含めてご理解いただけるように説明してまいりたいと、考えているところです。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１２月から説明会を順次されるということなんですが、７団体の方、だれでも参加できるような場を設けていただきたいんです。この点は、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"広報につきましては、広報紙等の活用も、現在考えてあります。時期を見て、さまざまな方法で、障害者施策について理解を深めるための広報には努めてまいりたいと考えているところです。","id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自立支援のところでは、ぜひそういう仕組みにしてほしいという要望を、障害者の方々からもたくさん上げられていると思うんです。ちょっとお聞きしたいのは、どういう専門職の方が、そこの体制がどうなっているのかということを一つ説明を求めました。","respondent":"西島障害者福祉課長","answer":"説明の件ですが、対応も違いますので、個々の団体ごとに説明をしてまいりたいと考えています。広報のお話をしましたけれども、どういう形になるかはこれからですが、詰めてパンフレットを配布してまいりたいと考えているところです。","id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここに対しても説明会ということで設けていただきたいということで、ぜひ要望をしますので、ご検討をよろしくお願いします。手話通訳は無料でぜひお願いしたいと思うんですけれども、ここはどういう形で決まってくるのか、ここら辺のところも説明を求めました。","respondent":"西島障害者福祉課長","answer":"それから、この制度が稼働するに当たりまして、国のほうも、現在のヘルパーの資格をとっている方に対する研修を実施するようなことも聞いてあります。地域生活支援事業について、ガイドヘルパーも地域生活支援事業に入りますので、総合的に検討している中で。","id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区で、大まかにでも結構ですけれども、わかったらひとつ教えてほしいと求めました。何か１,０００万円ぐらいの減収になるというのが書かれていたんですけれども、サービスの点でどうなっていくのかというところも、説明を求めました。","respondent":"西島障害者福祉課長","answer":"ここら辺は、現段階では、ちょっとお答えはできないと考えています。まだ明らかではございませんけれども、その辺についても、国は一定配慮をした政省令が出てくるんだろうと判断しています。","id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"お金をとっていくということですから、やっぱり応益負担というのは、根本的に障害者福祉と相いれない制度だと思うんです。こういう方向で、区のほうからも言っていただきたいという要望を述べて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"山路委員","kind":"質問・要望","question":"検討課題としてお考えになられるか、どうかということについて、ちょっと質問させていただきたいんです。２ページの(4) の地域生活支援事業で、この辺については、どういうふうにお考えか尋ねました。","respondent":"西島障害者福祉課長","answer":"どちらかというと関心が低いということがありますので、正しく理解していただけるように、これからも努めてまいりたいと考えています。","id":"exchange-058"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"どういった施策に取り組まれているのか、そういった部分を、しっかりと調査をしてほしいと求めました。高校生ですとか、そういった年の離れた子どもたちの交流の活動など、そういった部分をしっかり調べてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"須藤委員","kind":"質問・要望","question":"先様の、いわゆる社会保障に対する税体系がどういうふうになっているのかというものを、一緒にあわせて調査をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/948006?Template=document&Id=3130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":58631,"voices":159}},{"id":"h17-20051129-8","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"建設委員会","time":"午前１０時０４分～午前１１時２２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"平成１７年請願第５号 投資用ワンルームマンション建設計画地の公園化に関する請願","agenda":"平成１７年請願第５号 投資用ワンルームマンション建設計画地の公園化に関する請願","exchanges":[{"speaker":"林（和）委員","kind":"質問・要望","question":"そのときには相当の時間、１回目だからいきなり結論を出すというのかどうかということで、そのときには継続という状況でございました。文化財保護法に基づいて、試掘の方もしっかりとやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"現地を見せていただいたりお話を伺ったりさせていただいて、今までの状況等を勘案いたしますと、状況にあまり変化がない。私どもとしては、今の状況の中では、もう１回継続にしていかざるを得ないのではなかろうかなと思う次第ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"課長の説明のところでは、私は聞きとれなかったんですけれども、今、土井委員が言われた、地裁での中身をもう少しよく教えていただきたいんですけれども。","respondent":"浜脇住宅課長","answer":"建築主の方から私道の上の方の中央に住民がポールを設置したのに対して、東京地裁に妨害排除仮処分の申請をしたということで、その審議の内容についてはつかんでございません。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"わかりました。私もよくわからないんですけれども、じゃあ、実際に地裁での結論が出ると予想される期間というのはどれぐらいなんか尋ねました。","respondent":"浜脇住宅課長","answer":"今回の場合、ちょっとわかりません。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"これはもうどこから見ても明確なわけですから、ここでの請願は公園にしてほしいということですけれども、二つの面があるんだと思います。ただ、先ほど申し上げたように、地裁との関係で言えば、もう一度様子を見ざるを得ないのかなというような気がします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"今回の場合には、そういう特色のあるものを何かメインにしたりとか、そう考えていける部分があろうかと思います。ですから、結果を出すということで進めてほしいというのが意見で、結果を出すという方向でまとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"堺委員","kind":"意見","question":"私は、当事者間で早い時期に話し合いがつけば一番いいと考えています。２６日の委員会以降、委員会としては不本意かもしれませんが、今の段階では継続という扱いの方が妥当かなという気がいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"大西副委員長","kind":"意見","question":"先ほど課長の話の中で、１１月１日以降に事を慎重にするようにということで、その辺のところをもう少しわかりやすく話していただけますか。どういう趣旨なのかがよくわからなかったので、最後の部分をご説明願いますとの意見を述べました。","respondent":"浜脇住宅課長","answer":"２１日に説明に回りまして、１１月２２日以降、説明に当たっているということです。その中で、私どもとすれば、解体に当たっては住民説明会を徹底してやってください。","id":"exchange-008"},{"speaker":"大西副委員長","kind":"意見","question":"住民の方々としても、皆さんの意見の中に少しありました、裁判の係争中ということは別個としてとらえてもいいんではないか。これは、私の個人的な考え方ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"土井委員","kind":"意見","question":"いろいろ議論しているわけですけれども、この問題には中身が二つ入っているわけですよ。８階建てが建てられるということに対する問題と、その辺を含めると私は、もう少し議論を含めて推移を見た方がいいという判断をしておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"林（和）委員","kind":"質問・要望","question":"もう２カ月たっているわけですから、そういう意味で９月２６日は継続審議になっているわけですから、それで今回に伸ばしているわけですから。なかなか厳しいかもしれませんけれども、できるだけご要望にこたえていただけるように努力をしていただきたいものであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"私は前回、この請願を審議した後の事業者と住民の説明会に１度だけ参加をさせてもらいました。どっちかというと３対３で分かれているという形になりますけれども、私の方は構わないという立場を、とりあえずお伝えをしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"大西副委員長","kind":"質問","question":"８階だけで、今のまますぐ採択ということは、まだ少し議論の余地があるんじゃないか。最初の質問のときには、原則では継続が望ましいのかなと言っていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"それなりに私もメモってあるんですが、間違えるといけませんので、念のためもう一度確認をする意味で質問してよろしいでしょうか。仮に建築確認の申請書が出れば、その当該地については、梶原氏の館として発掘調査が必要になってくる。","respondent":"岩田まちづくり事業部次長","answer":"土地の区画の形質の変更をこの地区内で行う場合には、土地の試掘を行い、これは事業主の協力で行うということになります。地区の問題と、そういったいろいろな考え方がおありになるということで、これが前回お答えさせていただいた内容です。","id":"exchange-014"},{"speaker":"堺委員","kind":"確認","question":"そうすると、前回の説明の中で、事業主の建築確認の申請書は出ているということか尋ねました。","respondent":"浜脇住宅課長","answer":"先ほども申し上げましたけれども、１０月１９日に確認申請を、品川区の建築主事が受けつけています。まだ審査中であります。","id":"exchange-015"},{"speaker":"堺委員","kind":"確認","question":"そうすると、さっきの建築確認の申請が出れば、事業主が当該地を試掘するという。審査が終わった段階で試掘に入るんか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"私どもは、きちっとまわりの方にご説明をして、理解を得るようにという指導に基づいて説明をして回っているという段階です。お話し合いができておりませんので、昨日着手をするという報告は受けておりましたけれども、昨日の段階では着手しないで延期になったです。","id":"exchange-016"},{"speaker":"堺委員","kind":"確認","question":"解体して更地にして、建築確認申請書を受理されるかといったら、そういういうことではないだろうと思うんです。私個人はそのように思います。","respondent":"岩田まちづくり事業部次長","answer":"私どもが今、業者から聞いておりますのは、まず建物を解体し、建物を除去した後に土地の試掘を行う。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"逆に、試掘調査をして、本調査をして、ここは歴史的にもあるいは教育的にも保存する場所ですと東京都が認定をしたという表現になるのかわかりませんが、そうなった段階で、東京都がお金を出して、それにふさわしい整備をしなさいという形になってくるということか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"教育委員会の考え方によるんですけれども、それから地主の間で、今度は交渉に入るわけですね。あるいは地主の方が別の方法として保存する方法をお考えになるかもしれませんが、この場合どうだということは、まだ申し上げられない状態です。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"その段階では、地主さんの意向というのが非常に大きなウェイトを占めてくるんですか。あるいは「そこまでしてやりません」という地主さんの思いの方が、結論を出すに当たっては比重が大きいということですが、それはどうなんか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"それで保存すべきとなれば、これは法律上、地主であろうと、それを破壊、あるいは変更という行為は禁止をされます。ありうるということで、それはその時点になったときに、区と地主の方でどうするかということを決めるということになります。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問","question":"ですから、そのときに調査をしなくちゃわからないということですから、仮にそうだということが断言できるとなれば。この案件についてはきょうの段階では継続ではどうかなと、私は個人的には、今の時点ではそう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"堺委員","kind":"質問・要望","question":"所管の方でも、ぜひひとつ近隣の方々の意向を受けて、事業者の方に誠意ある対応をするように行政指導をしていただきたいです。されているかとは思いますが、念のため、行政の方にしかるべき行政指導を重ねて強力にお願いしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"の水上バス運行便数の変更","agenda":"の水上バス運行便数の変更","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"昨年度は３万１,０００人にまで落ち込んだということですけれども、これはどういうことか、何か原因があったんですか。わかりませんか。","respondent":"藤田道路公園課長","answer":"水族館の利用の減少というようなことも若干はあろうかと思いますが、大きくは、この航路に限る話ではなく、水上バス全体のご利用の方が減ってきているということで、水上バスというような形での運行が大変厳しい状態だということで、見直しを図りたいということです。","id":"exchange-022"},{"speaker":"林（和）委員","kind":"質問","question":"水上バスの利用者が少なくなったというのは、何か原因があったんか尋ねました。","respondent":"藤田道路公園課長","answer":"私ども、確認している中では、海の上を走るということで、さまざまなメリットもあろうかと思いますが、東京の中の交通ですので、鉄道等の便利さと比べて、時間もかかるというようなこともございまして、伸び悩んで、若干落ち込んでということと確認しています。","id":"exchange-023"},{"speaker":"土井委員","kind":"意見","question":"足とか楽しみとか、そういうものも、水族館だけではないものを何とか維持をしていかなきゃならないことがあるんじゃないかと思うんですね。ぜひまた、そこら辺、話し合い等の中でやっていっていただければありがたいと思いますとの意見を述べました。","respondent":"藤田道路公園課長","answer":"１便を減らせばそれでいいんだということではなくて、水族館、そういうことをこれから一生懸命考えていこうよということで投げかけてあります。その辺も含めまして、水上バス事業者の方とお話をしていきたいと考えています。","id":"exchange-024"}]},{"id":"topic-03","title":"ます。 ──────────────────────────────────────────── (2) 戸越幹線貯留管整備工事その３の着手について 次に…","agenda":"ます。 ──────────────────────────────────────────── (2) 戸越幹線貯留管整備工事その３の着手について 次に…","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"工事その１、それからその２、その３が、完成するのが１９年２月の予定になっているわけですけれども、これができた時点では、雨量の何ミリ対応というか、それはどうなんか尋ねました。","respondent":"原田下水道河川課長","answer":"以前は５０％と設定させていただいていたんですが、今は８０％ということで、５０ミリ対応だです。それから、その１工事につきましては、これは平成１１年３月に既に完成しています。","id":"exchange-025"}]},{"id":"topic-04","title":"東急大井町線旗の台駅改良工事","agenda":"東急大井町線旗の台駅改良工事","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"エレベーター、それからエスカレーターが全く設置されていないという駅もありますけれども、全体がこう進んでいくんでしょうか。ここの近くでは下神明駅にもありませんけれども、その辺の見通しみたいなものがあれば教えていただけますか。","respondent":"阿部都市計画課長","answer":"２０１０年までにバリアフリー化をするということになってありますが、東急の方には、私どもの方からバリアフリー化について申し入れはしています。今申し上げたとおり、２０１０年ということになっていますので、申し入れはしています。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"土地がないとつけられないみたいな話も聞いているんですけれども、その辺、の申し入れをしていくということで理解していいですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"戻ってきて出ないと身障者会館にスロープを通って出られないということで、大井町駅からの方たちは皆さんそういうことで旗の台の身障者会館に行っているんですけど、これでできることになるんか尋ねました。","respondent":"阿部都市計画課長","answer":"下の切りかえ後というのをごらんいただきますと、大井町から二子玉川に行くほうですので、下り線のところにエレベーターを設置しますので、そうしますと、ここをおりていただいて、新南口、これが身障者会館に行けますので、行けるようになります。","id":"exchange-028"},{"speaker":"堺委員","kind":"質問","question":"１日でも早くあそこを何とかしてほしいという、ぜひご努力をお願いしたいと、重ねてこの件についてはお願いしておきたいと思います。身障者会館とかりぼんとか、いわゆる区有地がありますが、今度の工事等にかかわるところには周辺に区有地というのがあるんか尋ねました。","respondent":"阿部都市計画課長","answer":"りぼん、その近辺ですね。保育園があります。","id":"exchange-029"},{"speaker":"堺委員","kind":"質問","question":"今、お話があった３カ所以外に、もっと駅に近接しているというか、そういう区有地はないんですかね。","respondent":"阿部都市計画課長","answer":"今、申し上げた４カ所ぐらいの施設だと思います。","id":"exchange-030"},{"speaker":"土井委員","kind":"意見","question":"これのお金の関係は、どういう形になっているのか、ちょっと説明いただけますか。東急が全部出してやることなのか、都や国や区が地元も含めてやっているのかとの意見を述べました。","respondent":"阿部都市計画課長","answer":"基本的には、急行の問題がありますので東急が負担をして、駅舎改良をしているということになります。","id":"exchange-031"},{"speaker":"菊地委員","kind":"質問","question":"急行の乗り入れで、１日の乗降客、現状とどの程度変わっていくのかというのと、大きく変わるんであれば、駐輪場の問題とか出てくるのかなと思うんですけれども、そこだけ説明を求めました。","respondent":"阿部都市計画課長","answer":"退避可能な施設にするという話ですので、それに伴ってどう増えるかという話は、まだ明確になってございません。駐輪場の話につきましては、区としては、東急を利用する中で、駐車場は用意していますし、東急としてもそういうことだと認識しています。","id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"全体的な教育の中における小学校とか中学校の今現在のあり方をこれからどうするのかという、お伺いしておりますので、申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"学校そのものではなく、教育委員会とまちづくり事業部との協議の中で、この学校改築計画というというのはどういう関係で出されていったのか。そういうところで、知り得る情報だけで結構ですので、お知らせほしいと求めました。","respondent":"上野都市開発課長","answer":"北品川五丁目第１地区の再開発準備組合におきます再開発の検討が進んできておるというのがありまして、北品川五丁目地区と御殿山小学校の敷地とを含む形で計画を検討するに当たって、現敷地位置での建替えを行うこととする方針を定めたものです。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"今の、都からの投げかけという時期はいつだったのか教えていただけますか尋ねました。","respondent":"上野都市開発課長","answer":"地元再開発準備組合の方で、計画に関する協議をこれまで進めてきましたけれども、その協議の中で前々から示されていたということです。大体いつということですけれども、過去数年間の協議の中で、そういう話が出てきたです。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"１６年だから、２００４年の４月とか３月とか、その宿題を与えられたのがいつかというところで。そこのところをもうちょっと詳しく、アバウトでなくて、「ここです」ということで教えていただけますか。","respondent":"上野都市開発課長","answer":"開発に合わせて整備するという方針が立ってございましたけれども、これを北品川五丁目第１地区の開発に合わせて整備すべき範囲と位置付けました。平成９年に、それから計画内容がある程度検討に着手された段階から、その中で折に触れて都から投げかけがなされたです。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"来年度には都市計画決定を予定しているとのことですから、一定程度のことはでき上がっているんだと思いますけれども、そこだけちょっと教えていただけますか。","respondent":"上野都市開発課長","answer":"再開発の計画を検討するに当たって、この組合の方で計画の詳細の検討を進めるということになってありますので、検討が進みしだい。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825107?Template=document&Id=3838#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":20092,"voices":92}},{"id":"h17-20051129-9","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"文教委員会","time":"午前１０時０４分～午後０時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"御殿山小学校の建替え","agenda":"御殿山小学校の建替え","exchanges":[{"speaker":"山村委員","kind":"質問","question":"日野中学校跡地がまた変わるわけですから、そういうものがあるものですから、今現時点で小学校を。本来だったら御殿山小学校はなくてもいいような話のやりとりをしたいんだけれども、そこら辺のことについて考えを言っていただけるとうれしいです。","respondent":"市川庶務課長","answer":"御殿山小学校の経営方針そのものが、御殿山小学校は御殿山小学校の特色ある小学校教育を進めていくという明確な方針を持ってありますので。","id":"exchange-001"},{"speaker":"山村委員","kind":"質問・要望","question":"はっきり言って土地が高い地域ですから、そんなに子供がいる層が来る地域じゃないと思いますよ、あそこの地域は。本当に前を見越して、また日野学園にあんまり奪われないように、いい学校環境をつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"１０年ぐらい前になるのかな、なぜ引っ込んだんだと言ったら、この「連動し」という意味はどういう意味なんですか。幹線道路４号と南北に出る幹線道路３号の用地を提供するという意味では連動するというのはわかるんですが、そのほかに意味合いがあるんか尋ねました。","respondent":"市川庶務課長","answer":"いわゆるこの道路整備に当たって、道路が拡幅されて、御殿山小学校の敷地のほうに壁面後退ということが実際問題起きます。これは都市計画サイドからすれば、同様にこの計画道路と再開発区域の間の土地の動向が、そういう意味での連動ということで使わせていただいたです。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"まだ配置図がわからないですから、この南北の幹線道路３号の右側に、もろに御殿山小学校は真っ暗になっちゃうという。ぜひ子供たちのそういう環境を守るために頑張っていただきたいなというふうに思うんですが、現時点で、もう少し詳しいものは出ているんか尋ねました。","respondent":"市川庶務課長","answer":"私どもが御殿山小学校建替えの方針決定をするに当たりましては、教育施設としての施設環境への考え方、こういったものについても話を聞いてあります。そういった話を聞く中で、そういうことが見込めるという立場で、私どもは小学校の建替えの方針決定をさせていただいたです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"ところが、我々がそれを見せてほしいと言うと見せない。ぜひ教育委員会のほうでも、早く状況をつかんでしかるべきものを、文教委員会でもあるならば見せてほしいということをぜひ要請したいと思いますとの意見を述べました。","respondent":"市川庶務課長","answer":"２点目の点については、私どももちょっと承知していない部分があります。ただ、今後の経過の中で、そういった資料をお示しできるものが出てくれば、考えさせていただきたいと思います。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"学校の建替えの計画を今して、７年後に計画して立ち上げるのも何か無理があるような気がするんですけれども、どうも納得がいかないですね。その辺の子供たちの予想とか、そんなものは考えているんか尋ねました。","respondent":"市川庶務課長","answer":"推計している２３年度までは、進学児童の推計といたしましては、これまでの平均的な数値の推移というのを同様に見込めるということが一つあります。","id":"exchange-006"},{"speaker":"松澤委員","kind":"意見","question":"御殿山小学校という中で、これ、建替え計画をするのは意味がないと思いますね。実際に、これが竣工して、できて７年後にどうしようかというときに考える場合に、ここで建替え計画することはどうも拙速のような気がしますとの意見を述べました。","respondent":"古川教育次長","answer":"ちょっと補足のご説明をさせていただきたいんですが、基本的に建替えの方針は先ほどご説明申し上げたとおり、五年。そして、この再開発の動向との関係の中で改築をしていくという考え方に私どもは立っているわけでありまして、このように考えております。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"道路は当然広がるわけですから、現状の形状が何らか影響を受けるわけですから、そういう方向性はあるんですか。それはいかがなんか尋ねました。","respondent":"市川庶務課長","answer":"学校改築事業そのものに対する再開発事業からの資金的な支援といいますか、そういったものは聞いてございません。再開発事業の一環として、例えば整備とか、そういったものは当然のことながら出てくるものだというふうに見込んでおります。","id":"exchange-008"},{"speaker":"沢田委員","kind":"提案","question":"開発で将来あと７年間でどうなるかわからないからもう少し見てというのもあるんですけど、今、この地域はマンションラッシュです。だから、私はどうもこの提案は割り切れないということだけ、質問ではないですよ、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"山村委員","kind":"質問","question":"本当は言っていいかどうかわからないんですけれども、逆に１校１校にかけるお金というのは多く使えるものじゃないんですかと思ったりするんです。意見にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林委員","kind":"提案","question":"御殿山小学校もまた地域の核となって、そういう意味合いのある建替えをぜひ、この際ですからお願いをしたいなというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"存続してほしいという住民の要求が出てくるのは当然ですから、私の意見なんですが、ぜひそれを言っていただきたい。要望も含めて、ちょっとその辺の見解というのをちょっと言ってほしいと求めました。","respondent":"市川庶務課長","answer":"ご質問の前提とされた、これは今後建つであろうマンションというものは一切見込んでございません。これまでと同じような傾向があるということで、説明させていただいた次第です。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"学校が先に建っているとか、ここ一帯につくるということになるので、学校を先に建てるということはできないんでしょうか。７年かかっちゃうんか尋ねました。","respondent":"市川庶務課長","answer":"具体的な事業予定、事業日程が示されてまいるわけですけれども、それといかに交差していくかということを判断していく必要があると考えています。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、８年間の動向があると思うんですが、建築を進めていかざるを得なくなるんじゃないかというふうに感じます。大変な思いを皆さんされているという現状を考えると、その辺はしっかり見ていただいて、計画を立てていただきたいというふうに要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"意見","question":"ボランティアの保護者の方たちの説明が９時からあるので、他のどういう動きというところ、全体像が見えなくなっちゃうと思うんですよね。ですので、私は希望して９時からとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"私、先に行っていいですか。９時から行かせてもらって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270991?Template=document&Id=4556#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":15691,"voices":67}},{"id":"h17-20051129-5","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"総務委員会","time":"午前１０時０５分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"それから、ほとんど保健所ということで、申請１４件ということですが、保健所関係でどのぐらいの申請件数があるものなのか。全体の中の１４件ですけれども、現状としては保健所関係というのはどのぐらいの数なのか、その２点との意見を述べました。","respondent":"小野情報システム課長","answer":"比較的ここで取得するＩＤパスワードで対応できるようなものについてはお控えいただくという形で対応していただいてよろしいのかなと思います。今回のモデル実施をする中で、保健所関係の手続については、引き続き検討して広げていくということで。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ある程度、今は申請書の電子発信ができる部分で簡単な部分は考えてほしいと求めました。それは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"三村委員","kind":"質問","question":"利用が１件とか２件という話を聞くと、やはり使い勝手がいいシステムをしていかないと、なかなか利用が進まないのかなと。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"原委員","kind":"確認","question":"一つだけ確認をさせてください。東京電子自治体共同運営サービスはどういう団体で、どういう事業を今まで請け負っていて、どういう形で品川区が係わっている団体なのか。","respondent":"小野情報システム課長","answer":"今ご説明いたしました電子申請と電子調達を東京都内の区市町村が共同して運営していくという目的のためにつくられた協議会です。実際の運営システムだとかサービスの運営については、この協議会の中で決めて実施するという形になります。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうすると、この分担金というのがどのぐらいの費用がかかって、もう一つは事業の範囲ですが、今後もっとほかの利用価値というか、利用方法とかいろいろあると思うんですが、その辺のところがどういうふうになっているのか説明を求めました。","respondent":"小野情報システム課長","answer":"今回ご説明いたしました電子申請サービス、それから入札関係の調達サービス、お金の決済のマルチ経営等のサービスも行えるようになると思います。それから、利用者に対する問い合わせについても、区民の方の手続についての問い合わせとか、こういう対応についてはコールセンター。","id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"そうすると、将来的には使い方が広がってきて、今お話しされたような職員も使えるし一般の方々も使えるということなので、利用の程度というのはもっといろいろ考えられるわけか尋ねました。","respondent":"小野情報システム課長","answer":"料金の決済等も含めて出てきますと、かなり手続が可能になりますので、今１４手続で出発しますけれども、かなりの幅の手続が将来的には可能になると考えております。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"品川区の負担で１年間１,０００万円、どういう成果があったら進めていくのかとか、いわゆる費用対効果をどのように考えているのかと思うんです。例えば利用が少ないのにやっていくのかということですとの意見を述べました。","respondent":"小野情報システム課長","answer":"確かに、電子申請については、新聞批評でもなかなか利用が進んでいないという報道もございまして、いろいろ難しい点があります。電子申請ですので、今回のモデル実施は、その方法を実際のモデル実施の中でいろいろ検証をして工夫していくためのモデル実施と考えております。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"確認","question":"住基カードもそうでしたけれども、無理に進めるみたいないことがあってはいけないと思うんです。一つ確認しておきたいんですけれども、今までの手続は当然変更してやるだろうと思うんですけれども、そこのところはどのように考えているのか。","respondent":"小野情報システム課長","answer":"電子申請は新しい手続の方法を一つ増やしたということでございまして、従来から行っているものについては従来どおりです。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"費用をかけているからということで、今までのところを無理な形で整理していくとか、そういうふうにならないようにしてほしいと求めました。単純な質問ですが、つじつまが合わないとはねられるとか、そういう仕組みになっているんか尋ねました。","respondent":"小野情報システム課長","answer":"価格の訂正をインターネットを通じて利用者とやり取りができるようになっておりますので、そういった形で訂正をして直していきます。それから、申請サンプルを利用されている利用者が、今の手続がどの審査の段階にあるかという、進行状況を見ることができるようになっております。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"今の件ですけれども、例えば記載の方法でよくわからないことがあると、先ほどコールセンターというお話があったんですけれども、そうするとコールセンターは実務的なところで、申請書の書き方も含めてかなり専門的な知識を持った方が対応するということか尋ねました。","respondent":"小野情報システム課長","answer":"そのとおりです。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点確認ですけれども、この１,０００万円というのは前回の委員会で出た電子入札に係わったときには１,０００万円ですよね。新たにここで１,０００万円を払うというニュアンスに聞こえているんですけれども、その辺だけ確認しておきたいと思います。","respondent":"小野情報システム課長","answer":"全部のサービスを含めて電子申請、電子調達、決済、コールセンター、ヘルプデスク、これらのものを全部含めて年間１,０００万円のインターネットに係る経費です。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今までの質疑が、新たに１,０００万円が載っているような答弁だったような気がしたので、確認しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"藤田委員","kind":"質問","question":"この１年間で保健所等の手続の(1) から(14)までの件数はどれぐらいあったのか、わからなければわからないでいいですけれども、わかれば説明を求めました。","respondent":"小野情報システム課長","answer":"申し訳ございません。今、手元に資料がございません。","id":"exchange-013"},{"speaker":"高星委員","kind":"質問・要望","question":"どうも自分が苦手なものですから、正直私はよかったと思うのは、去年の確定申告を役所でやりますね。そういったメッセージをやはり区民にどうやって発信していくかということ、その辺の考え方をお聞かせいただきたいなと思います。","respondent":"小野情報システム課長","answer":"営業者ということで、繰り返しある程度使うことがあるということでメリットがあるのではないかという観点で特に選ばせていただいたものです。今回のモデル実施の中で、できるだけ使い勝手のいい、使われるものを選んで進めていきたいと考えております。","id":"exchange-014"},{"speaker":"高星委員","kind":"質問","question":"ささいなことだけれども大事なことだと思うので、コマーシャルする必要があるだろうと思うので、よろしくお願いしたいと思います。あまりにも数値が上がらないと、何のために課長の席を設けたのかわからなくなってしまうので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中島副委員長","kind":"質問","question":"今の話と関連するんですが、画面に人が映って、質問に対していろいろアドバイスをしてくれるシステムがありますね。こういったことは今後は取り入れていく予定はあるのか尋ねました。","respondent":"小野情報システム課長","answer":"東京電子自治体共同運営サービスの中では、今のところこういうサービスをシステムに盛り込むという予定はございません。利用者の方のご意見を聞きながら、その辺のところをご要望等お聞きしてより良いものにしていくよう、私どものほうも考えております。","id":"exchange-016"},{"speaker":"中島副委員長","kind":"質問・要望","question":"やはり高齢社会といえども、今の若い人たちはほとんどこういうものに精通していますから増えてくるのは確実だと思うんです。そういうことも早いうちから検討しておけば、余分な予算をかけなくても効率的にいくと思いますので、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう要望にこたえてほしいと、そういう要望が考慮されてもいいのではないかと思っているんですけれども、そういうのが可能だったのではないか。計画をつくるときには議会でもかなり声があったのに、どのように生かされるのか疑問なんですけれども、そういうところはどうか。","respondent":"日下部企画財政課長","answer":"ただ東品川海上公園につきましては、特性をうまく生かした形での整備ということで進めさせていただいたと、そういう経緯があります。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やはり、それだけの要望が強いというのは、計画をつくる時の住民要望の把握の仕方というか。今後のときは、ぜひそういうところを考慮していただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それから、旧東海道あたりを散策している方を引っ張れるような、そういう考え方を持っていただければ、せっかくの公園なのでその辺の検討を。この辺の今後の予定はどうなっているのか、お答えできる範囲で結構ですけれども、お願いできればと思いますとの意見を述べました。","respondent":"日下部企画財政課長、鷹倉経理課長","answer":"確かに、昨日まいりまして、あまり人がいらっしゃらなかった。では、ちょうどそういう動きもうまくタイミングが合ってまいりますので、有効に活用されるようになってくるのではないかと承知しています。それで、丸印の書いてあるところが道路側に面しておりますので、公園側としても道路に向いている用地を確保したいというのがあります。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もう既にあれだけいい公園になっている中で、もっとアピールしていくべきではないか、もったいないと思うんです。せっかくなら、もっと人に来てもらえるようにやってもらいたいということで、その辺のお答えがいただければとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"ちょうど１２月１日号のカラーのトップで紹介いたしましたので、あのページがとても好評なので、効果があってきれいだから訪れてくださればと思います。","id":"exchange-021"},{"speaker":"三村委員","kind":"質問・要望","question":"昨日視察したときに、ほかの公園を見てきたときに、だれでもトイレの夜間の利用で不適切な利用があるということで鍵がついていたりします。実際に利用したいときに利用できないという話も聞いていまして、その辺はどのように対応されるのか、わかれば教えてほしいと求めました。","respondent":"鷹倉経理課長","answer":"トイレの使用までは把握していないのですが、この辺のところは必要かなと思いまして、所管の方に伝えたいと思います。","id":"exchange-022"},{"speaker":"三村委員","kind":"意見","question":"もう１点、私は結構近いのでよく利用するのですけれども、引き綱を使わずに犬を放されている方が実際にいます。ドッグランとして使えるスペースをつくっておいたほうがトラブルになりにくいのではないかと思うんですけれども、ご意見をとの意見を述べました。","respondent":"日下部企画財政課長","answer":"スペース的に限りがありますので、ドッグランを設置するとなると、一定のスペースが必要になります。ただ、先ほど申し上げましたように、当面はそちらのほうをご活用いただくということでお考えいただければと考えております。","id":"exchange-023"},{"speaker":"藤田委員","kind":"質問・要望","question":"「水とみどりのネットワーク」と言いますけれども、よく２３区の自治体でも苦慮して、それをやっている。そうするとやはり自然を感じられるような公園になると思うんですが、答えられなかったら結構ですが、伝えていただければ。","respondent":"日下部企画財政課長","answer":"実は昨日、こちらの絵でまいりますと右手のほうに蛇行している川のような図がありますけれども、子どもたちが遊べるような空間になってあります。時計の関係につきましては、この表示だけではわからない部分がありますので、所管にしっかりと伝えてまいりたいと考えております。","id":"exchange-024"},{"speaker":"原委員","kind":"質問","question":"ここで聞いていいのかどうか、かなりの広さのものなので、管理体制というのはどういう形を考えていらっしゃるのでしょうか。昨日も一生懸命雑草を摘んでいましたけれども、どういう形を考えてられているのかと思うんだけれども、わかったら説明を求めました。","respondent":"日下部企画財政課長","answer":"今、ご指摘のように、大変広い空間です。管理につきましては、こちらについては確か民間の事業者に委託をして、かなりきちんとした形で管理をしていくという体制になってあります。","id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"４,７００m2ぐらいの広い公園づくりですけれども、水とみどりのネットワークと言われるように、中心的なスポットだと思うんです。これだけ広い公園ですから、３０年経った後、どうか尋ねました。","respondent":"日下部企画財政課長","answer":"実は昨日、平成１８年度に予定しております下水道ポンプ場の脇の空間が、このところに重点的に木を植えていくという説明が昨日なされておりました。ですから、そして工事ということで進めてきておりますので、少し中長期的にご了解をいただければと思います。","id":"exchange-026"},{"speaker":"本田委員","kind":"質問・要望","question":"２０年、３０年経ってみないと本当のよさはわからないですけれども、つくった当時はどうってことなかった。そういう点で、その辺の植栽については十分考えていただきたいなと感じておりますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"中島副委員長","kind":"質問・要望","question":"今のお話しを聞いていて水と緑のネットワークということで、非常にこれから有名になる公園かなと思っているのですが、赤い水門がありますね。あれが目立ってしまって、あの辺は東京都だと思うんですが、東京都に要望するということは可能なのか尋ねました。","respondent":"日下部企画財政課長","answer":"水門につきましては、ご質問にもございましたけれども東京都港湾局が所管しているものです。まちづくり事業部にそういうご意見があったということで、改善できるのかどうか、その辺は伝えておきたいと思います。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう１点、これも所管が違うからあれですけれども、あまり近くに自転車置場がないんですよ。少し印象が薄かったので、気になったので、要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"三村委員","kind":"質問・要望","question":"今回、月額３００万円で貸し出しをするということですけれども、ほかと比較してもう少し高い金額で貸せるようなところがあったのか。それから、３００万円の根拠があれば教えていただきたい。","respondent":"鷹倉経理課長","answer":"ちょうど私ども学校を検討していた中で、どうだという話が来た経緯があります。その中で学校のほうが難しいというのがあって、この際検討させていただいたというようなことです。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、もっと一般的に広くこういう施設がこういう期間で空きが出るので使いませんかと出してくるのか、どっちがこれからの考え方なのか。すべて特殊事情に合わせて指定してしまうのか、考え方としてどちらか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"この経緯の部分、ほかとの交渉は私のほうがあたっているので、説明します。かつ区民のために利用できるものという、決められた形で再開発組合に声をかけた近隣の私立の学校ということ形で、個別に交渉してきたです。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺が今後も利用していくというものが何でこっちになったのかということ。施設としてある程度区がやっていくとすると、どのぐらいの負担が出ていたのか、その辺を教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"できればそこの地域、そういった方の利便性も考えてすることが、そういう形での条件つきにしたほうがいいのではないかということが１点。初期投資を見込んだ上でのぎりぎりの線で交渉したという形なので、こういう形での暫定期間という形にしたところです。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"意見","question":"月額３００万円というと大きいと思うんですけれども、このまま行ったときにこれで５面つくるというと、体育館のワンフロア部分だけで５年使うのか。もしワンフロアだけ使うのだったら、２階部分とかもっと活用できる部分がないのかとい点、その辺をまずお願いしますとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"屋上に１面、それから温水プールの上にふたをして１面という形で、５面を用意する形での使い方を想定しています。実際上、それぞれ工事をしてみて、使えるところは使っていきたいというような提案がある形です。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"周りに影響が出ないかどうか、その辺が心配なので、その辺の対応を考えていただければと思うんですがとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"営業時間としては朝９時から２４時まで考えているということで、夜１０時までということで時間の制限をしているということです。夜８時以降はサイレントタイムということで、近隣に迷惑がかからない形での運営をしていただきたいと、指導していきたいと思います。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"五反田は１１時半と言っていても、あそこはあまり住まいがない部分だと思うんです。周りに影響が出るといけないと思うので、その辺は、折衝をうまくしてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"高星委員","kind":"確認","question":"貸付相手のアビロージャパン(株)がどういう会社かわからないのですけれども、なぜそこが相手なのかということを聞きたいと思っているんです。アビロージャパンという形になっていたのかどうか、その辺のところだけ確認する意味でお聞きしたいなと思います。","respondent":"榎本行財政改革担当課長","answer":"それから、その部分をどのように対応するかということでつくったという経緯がありましたので、少し場所が移ったという形で使えるということ。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"北品川区五丁目第１地区市街地再開発の進捗状況といいますか、その辺はどんなところまで進んでいるのでしょうか、計画より大分遅れておりますね。そうすると、どのぐらいの期間なのかな、そこのところをどのようにみているのかお聞かせほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"詳しいところはわかりませんけれども、私どもが聞いている範囲ですと、来年にはある程度目処が立って、着工時期もここ二、三年以内にはつくという形で聞いておりますで、その間の暫定利用という形での利用方法を考えて、こういう形で貸付をすることにしたということです。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問・要望","question":"年間３,６００万円を負担して、要望があるのであれば、そもそもこういう要望を区がしっかり受けとめる必要があると思うんです。少し伺いたいのですが、品川区民はいろいろ特典があるということが書いてありますけれども、実際上、どのぐらいの利用料になるのか。","respondent":"榎本行財政改革担当課長","answer":"実際上、フットサルコートが今後１０年、２０年という形の利用があるのかどうかを見た上で今後検討したいと思います。区内の在住・在勤者の利用が３割から４割ぐらいという形で聞いておりますので、そういう形での利用をしていただきたい形で決めさせていただきました。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、今までの区の施設との比較でいっても、例えばフットサルですとテニスコートの大体２割分でできるといいます。区がそのままやっていた場合、今度は貸し出しての場合と、利用者の側から見たらどのぐらいの料金の差が出てくるのか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"そういう形での比較はしておりませんけれども、実際に今現在の利用の需要がその金額でもあるという形で民間事業者が参入してきているという形ですので、そういった形での有効活用を図っていきたいという考えです。","id":"exchange-039"},{"speaker":"宮崎委員","kind":"意見","question":"やはり、そういうところをしっかり計算しなければ、一体３００万円というのはどういう根拠なのかということになってくるのです。どうやって３００万円になってきたのか、その根拠が全くわからないですねとの意見を述べました。","respondent":"新美企画部長","answer":"したがいまして、今の古い総合体育館は普通財産にし、北品川五丁目第１地区市街地再開発の用地として活用していくという方針が固まっている。先ほどの経過から申し上げますと、学校側に検討をしていただく期間がございました。","id":"exchange-040"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やはり、そこには区民の要望から出発する考え方が欠落しているのではないかと、この感想で述べておきたいと思います。私は住民の要望があるのに企業にすっといくというのは、やはりどう考えてもおかしいということを申し述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594587?Template=document&Id=1704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":29471,"voices":111}},{"id":"h17-20051130-11","meetingId":"h17-cm11","date":"2005年11月30日","dateIso":"2005-11-30","committee":"自治制度特別委員会","time":"午前１０時１０分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"本日の進め方でございますが、まず初めに、(3) の基礎的自治体（特別区としての品川区）のあり方","agenda":"本日の進め方でございますが、まず初めに、(3) の基礎的自治体（特別区としての品川区）のあり方","exchanges":[{"speaker":"石田委員","kind":"質問","question":"この前ご説明をいただきまして、大分忘れかけてきているところもありますが、お伺いします。そこの部分をどう取り上げられて、これが出たことによって、どういう動きになっていくと我々は理解しておけばいいのか教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"たしか道州制の問題につきましては、来年の２月に最終報告がまとめられるということで、いろいろな検討が進められているわけです。地方制度調査会の検討の俎上に上るということは、そういうのが必要になってまいりますので、そのように考えております。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"もう一段教えていただきたいんですが、論議の俎上に上がるということは、「俎上」というのはどこの俎上に上がるんでしょうか。は別の機関をつくって、そこでもう一回議論をしていくのかとか、その「俎上に上がる」というのは、どこに上がると今、考えればよろしいんか尋ねました。","respondent":"日下部企画財政課長","answer":"そういった意味におきましては、それから当然、議会におかれましてもいろいろ今後のあり方を検討する上での一つの論議の素材として活用していただく。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"もう一段教えていただきたいんですが、今言った主要５課題の部分も含めて、都区のあり方をもう一度議論をしていこう。１２年の会社があって、１７年とあると、１７年間際になってこないとやらないというのもあるじゃないか尋ねました。","respondent":"日下部企画財政課長","answer":"私が承知している限りでは、期限をどのくらいに設定してという形での取りまとめといいますか、考え方は出されてございません。どういう形で受けとめて、そういう中でいろいろ論議がなされた上で、また次のステップでということになるのではないかと思います。","id":"exchange-003"},{"speaker":"本田委員","kind":"質問","question":"つまり、２つはみんな似たようなものですけれども、３つのシナリオはかなり違った形態ですから。当面の問題解決にも逆に２３区は結局そろっていないということにもなりかねないと思うんですけれども、その辺の議論はどう進んでいるか尋ねました。","respondent":"日下部企画財政課長","answer":"この辺を中心にいろいろ議論が進められておりますし、先ほど申し上げましたように、来年の２月には一定の方向性が出る。今回の報告書というのは、いろいろな形でこれがたたき台になって、将来方向の検討に有効に生かしていけるのではないかと考えているところです。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"ですから、見解というか、出しておいた方がいいんじゃないかなと。見解を出しておくべきではないかなと、感じているところなんですが、そういう動きはないんか尋ねました。","respondent":"日下部企画財政課長","answer":"例えば読売新聞でも２３区の権限拡大を報告書提出、都区制度の解体をと、いろいろな形でマスコミでも大きく取り上げられた経緯があります。","id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"特別区協議会、特別区制度調査会、これは２３区側が自分たちの考えをまとめたということですね。東京都側も何らかの考え方を整理して、傾向を出すように言っていたんですけれども、それはどんな状況になるのかということを聞きたいと思いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"１つは自治制度のあり方、この内容の検討を進めているという中で、第一歩の行財政改革の指針というのが出されました。大ざっぱな中身ではありますが、そういう形での問題提起も盛り込まれていると、そのようなことで承知をしています。","id":"exchange-006"},{"speaker":"塚本委員","kind":"意見","question":"それに対する東京都側の返答、このレポートに対する見解がどういう形であらわれているのか興味があるところです。対抗できるようなものが時間的にどういうふうにできていくかなということが見えてこないと、今の私の理解でいいのかどうかということの意見を述べました。","respondent":"日下部企画財政課長","answer":"早急に一定の都側としての考え方を出さなければいけないと、おそらくそういう一つの危機感がばねになって、作業が進められたと承知をしております。ですからいずれにしましても、今後の東京都の検討の状況については十分、私どもも注目をしてまいりたいと考えております。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"今まで、もう１０年ぐらい前ですか、道州制というのはこんなものだよという、そんな話が出てきたのは。私たちに教えてもらいたいという意向があるんですけれども、こういうことが道州制の中で議論されていますよというのがわかれば教えていただきたい。","respondent":"日下部企画財政課長","answer":"第２７次の地方制度調査会の中で、これが大都市制度と並んで、検討課題になっておりました。今、道州制の論議が進められてまいりまして、道州制のエリアの検討プランというのが幾つか既に出されておりますし。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"ということは、道州制というのは別の言い方をドラスティックに言えば、都府県合併ということを求めているんだと理解していいのかと。道州制を本当に導入しようとしたら、どういう手順で、基礎的な考え方はどうなのかということをもう一度お願いします。","respondent":"日下部企画財政課長","answer":"最終報告は２月ですが、調査会の中でまとめられております中身でいきますと、あくまで都道府県の合併です。現状ではそういう状況です。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"東京都を見ると、人口規模では十分に大き過ぎるぐらい大きいですから、ほかのところがそうやってきて、埼玉県や神奈川県の周辺はどうなるんだと。東京都の位置づけというのは、その中でちょっと間尺が足りにくいところがあると思うんですけれども、その辺の議論はされているんか尋ねました。","respondent":"日下部企画財政課長","answer":"出されております考え方は２通りございまして、東京都全体あるいは２３区を絞りまして、そこを独立させるというのが１つの案です。議論がなされているというような２３区については、今、２案提示されているという状況で承知をしております。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"品川区の場合は真ん中ですから、その２３区でやるかどうか別として、あるいは制度的なものをみずからつくっていく。すなわちこのシナリオの１なのか２なのかも含めて、明快になっていくことではないかと思うんですけど、そんな解釈でいいか尋ねました。","respondent":"日下部企画財政課長","answer":"これを見ていただきますと、シナリオの１とシナリオの２というのが出ておりますけれども、シナリオの１の方は横の連携を形は変わっても保っていこう。それによって、こういう３つのシナリオが描かれてきているんだということで、私どもも認識をしています。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"それの中にやり方が２つある。２３区の区長がこのことを勉強して、そういうことをやっているという話も聞こえてこないんだけれども、どうなっているか教えていただきたい。","respondent":"日下部企画財政課長","answer":"ですから、これはおそらくこの報告書を踏まえて、今度は区長会で毎度これについて議論を交わすというわけにはもちろんいきません。最大の検討の素材として取り扱いがされていくと思いますし、それをもとにして、次のステップに進んでいくという形におそらくなってくると思います。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"中央区長におれのところをやったとか、やらないとか言われるのはおもしろくないという心理的な働きがあって、起きるかもしれない。解けてくる部分があるのではないかと思いますので、ぜひそういう基礎的な研究・勉強を積み重ねてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけお伺いしたいんですが、各区の権限というのは、逆に非常に落ちていくわけですね。真剣にやるのであれば、そこら辺の情報をどこまでどうやってとろうかという努力を特別区としてされているのか、ちょっと教えていただきたい。","respondent":"日下部企画財政課長","answer":"適切な対応ができるようにということは、私どももそういった意味では今回の報告もそうなんですけれども、２３区側の目だけでと。東京都の情報もしっかりとって、ひとりよがりにならないで、しっかりと客観的な見方も含めて議論を詰めていくことが大事ではないかと考えています。","id":"exchange-014"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"２点だけお聞きしたいんですけれども、当然あると思うんですけれども、その辺を説明していただけないかというのが１点。これから影響が出てくるという話がありましたけれども、その辺が区にどういうふうに影響が出てくるのか、そこもちょっと教えていただきたい。","respondent":"日下部企画財政課長","answer":"そういうことで初めて、地方間のバランスが保てるという考え方に基づいて、いろいろな取り組みが今、進められている。東京都はたしか６００億円ほどの減収になるということで、法人住民税の見直し問題が検討の対象に挙がっているということで承知をしています。","id":"exchange-015"}]},{"id":"topic-02","title":"特定事件調査(2) 清掃制度に関すること","agenda":"特定事件調査(2) 清掃制度に関すること","exchanges":[{"speaker":"若林委員","kind":"確認","question":"確認書の方なんですが、２番に行きますと、これはどういう捉え方をすればよいのか。尊重しつつ、一部は各区で判断するという意味を教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"２番が実態、その２つの事務については各区契約をまずすることができるということで、各区にすることができると。したがって、歴史的経過は経過として、今度は契約の方法論として各区契約ができるというのが２番のところになっているです。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"今までは清掃協議会とこの雇上協会ですか、それ以外のこの２項目目にあります資源および粗大ごみについては、具体的にはそういう理解でよろしいか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"ちょっと説明をすると、十分ご理解いただけなかった説明であったかと思いますので、雇上会社もしくは雇上会社で構成する団体との契約とする。粗大ごみにおいても、逆に言うと行わないということが、ここの確認の中でうたわれていることです。","id":"exchange-017"},{"speaker":"若林委員","kind":"確認","question":"こういう覚書をわざわざ前提にして確認書に判こが押されたということで、基調の方にあるこの確認書、この辺はどういうふうに具体的に。なので、この確認書によって、それを与えてまたという形を教えていただけますか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"先ほどご説明した覚書の別紙のところをおめくりいただきますと、市が当時の民間事業者であった者をいわゆる雇い上げを行うように請負契約に変えたと。","id":"exchange-018"},{"speaker":"若林委員","kind":"意見","question":"各区の対応になって、その代表である特別区長会の会長が２３区のものも含めて、その部分は引き続きお互いにまだ認識しましょうと。ただ、時代の流れに乗って、資源ごみ、粗大ごみの部分のところは、またこっち側で考えてきましたよというようなところで、理解をいたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"石田委員","kind":"確認","question":"確認書の件でお伺いしたいのは、経緯もすごくわかりました。この確認書をしたことで、本当の確認だけをしたのか、その辺を教えてほしい。","respondent":"岩崎環境清掃事業部長","answer":"なぜかといいますと、平成１２年の移管のときにこんがらがったまま、いろいろなものがそのまま来ちゃったという要素が非常に大きかったですね。ここでは申し上げられませんが、ぜひともこういう区の権限を十分に発揮できるような方向性で来年の４月を迎えたいと考えています。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"読みながらさまざま伺っていますが、最終末端のところに結局４トン混載でどっと来ると、幾らというぐらいの最終的な値段がありますね。もちろんわかっていらっしゃると思うんだけど、どれぐらいの影響があると思われているのか、そこら辺のところがわかったら説明を求めました。","respondent":"岩崎環境清掃事業部長","answer":"事業系は有料ですけれども、家庭系は今のところ無料なので、無料の方に紛れて出しちゃうと、ずるできるわけです。これの対策を今後、より強めていかなければいけないと考えているところです。","id":"exchange-021"},{"speaker":"土井委員","kind":"質問・要望","question":"確認書なんですけど、ここら辺が御苦労されたところなんだろうということを思いつつ、ちょっと聞かせてほしいと求めました。この「当分の間」というものは、先ほどの持ち込みのあれですと、１５年ごとに直そうとかいう、何かありますけれども、利用者は何もないんか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"押していきまして、清掃協議会は要らないという状況に持っていきたいなというのがこれまでの思いでしたし、これからの方針でもあります。","id":"exchange-022"},{"speaker":"土井委員","kind":"確認","question":"お伺いしているのは、この確認書はもともと東京都の入った覚書等々だったからということでいらっしゃるのかもしれないけれども、ちょっといかがなものかという意味なんです。","respondent":"中山清掃リサイクル課長","answer":"実際の協議でも全く都は、居合わせましたけれども、何ら発言もしていないということでございました。新たに改革をするのも区の中での感覚ということで、今回、協議をやった経過ということでの到達点ということでご理解いただきたい。","id":"exchange-023"},{"speaker":"土井委員","kind":"意見","question":"前の方で、その辺でそうなっているから、とりあえず１回は出てこないといけないなという感じです。何か環境保全協会とで当事者同士で決めますから、それが言われていないのについては、ちょっと違和感を覚えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"塚本委員","kind":"確認","question":"２３区が主体になってようやくここまで、清掃協議会もエンディングを迎えるようなところまで来たわけですから、御苦労さまでございました。何でまたこの人たちは親がかりのような顔をして出てくるのという印象を我々が受けるわけですから、そういうことでご努力願いますということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと確認も含めてなんですが、自治制度であるのか、区民に求めるというところは区民委員会での報告になるのか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"前回の委員会において、この内容について、いわゆる区の中の委員会で扱われることもあるという趣旨でしょうか。前々回で２３区としての、あるいは清掃一部事務組合の計画改定内容として当委員会で報告したです。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと区民委員会の方に入ってしまうのかもしれませんが、そのことについて、ホームページ上でほかの区では意見を求めますというようなこともあったんですが、品川区は今、どうなっているのか、説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"原本を閲覧して、パブリックコメントが出るように協力の要請がありましたので、現在行っております。パブリックコメントができるように、今、対応しております。","id":"exchange-027"}]},{"id":"topic-03","title":"特定事件調査、(1) 都区制度改革・主要５課題に関すること","agenda":"特定事件調査、(1) 都区制度改革・主要５課題に関すること","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"区長会の会長としてぜひ頑張ってほしいと求めましたし、どうも伝わってくる話は、実際は現状のままの方がありがたいんだよ。そういう乱れているようなところの区の発言みたいなものはやっぱり調整をしてほしいと求めましたので、ぜひそれはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"本田委員","kind":"提案","question":"議長の提案は結構ですし、都議会各会派が必ずしも区側の我々の要望に同一歩調をとっているようでもないと、ニュアンスが何か違いがありそうですね。そういう点で、せっかくの要請行動ですから、都議会の各会派にも統一の要望書なり要請行動をぜひ加えていただきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の委員会で、廃プラスチックのサーマルリサイクルについてもご報告いただいたんですが、ぜひ常にサーマルリサイクルを行っている大田区の第二工場に視察に行かせていただけたらと思っているんですが、時間の余裕のあるところで結構ですので、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918758?Template=document&Id=5586#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":33979,"voices":74}},{"id":"h17-20051130-16","meetingId":"h17-cm11","date":"2005年11月30日","dateIso":"2005-11-30","committee":"街づくり特別委員会","time":"午前１０時０４分～午後２時１８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件整理しています。","topics":[{"id":"topic-01","title":"公有地の活用に関すること","agenda":"公有地の活用に関すること","exchanges":[{"speaker":"三上副委員長","kind":"質問・要望","question":"その高速道路の下は通常の都道でありましょうか、国道でしょうか、道路が通っています。一時金で支払いを当然求めていくものではないか、そういった点を要望して、こういうふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"本間委員","kind":"質問・要望","question":"私どもの会派の部分は３行でまとめてありますが、当初、これを公有財産としてどのように有効利用していくかというふうなことで来ましたものですから。この短い３行の中に、補足すべきこととして皆さん方に、説明しているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"大きな１点目ですけれども、関係住民からの意見や要望の尊重を何よりも第一義とすべきだということです。繰り返しになりますが、公聴会や審議会など、幅広い区民の意見を本当に大事にしてあげて進めることを求めていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"伊藤副委員長","kind":"提案","question":"１番目は、新しい形で貸し出すわけですから、行政側にご理解していただきたいと考えています。それから４番目は、なかなか行政のほうは態度がそうでなかったものですから、それからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"なお、６項目要望をいたします。地域に開放していますグラウンドと第２グラウンドの開放を、２年間ですか、従来どおり充実をしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"提案","question":"ただ、いろいろな施設があるわけですから、今回の第一日野小学校の改築移転という形について位置づけを明確にしていただければなと考えています。当委員会についても要望も少し上げさせていただきましたけれども、それから、意見として述べさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ短期間で、住民に迷惑がかかりにくい方法に手を貸すべきであり、株式会社ＴＯＣに建築計画の再考を要望すべきであると思います。近隣住民への詳しい説明とともに、ご意見ご要望をよくお聞きして、住民の意向にできるだけ沿った方向で進めていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"その３年間、結局３年間で一気にやるということは、結局は第一日野小学校の校庭は関係なくなるということになるのですか。ちょっとそこら辺が、今まで一気にというところが視野に入っていなかったので、その辺を少し確認をさせていただきたいと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"テナントにとってもいいわけですから、やはり区の公有地ですから、そういう使われ方をしてもっていくということが大切じゃないかと。そのまま区も容認して貸し出すということは、そこはまだ交渉はこれからということなんですから、それはやむを得ないんじゃないかなと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"そうすると、ネット・無所属の考えというのは、ＴＯＣに貸してもいいということになるんですか。結局は、早く終わるということを考慮に入れているのであれば、ＴＯＣに貸し付けをしてもいいという内容でよろしいんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"例えば３期に分けてやるのか、２期に分けてやるのか、それも全然伺っておりません。その状況で今きちんと話せというのはちょっと無理があるんじゃないかなと私は考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"もう一度確認をさせていただきたいんですけれども、要はわからないというか、判断できないということでよろしいんですか。どういう意向なのかということはもう少しお話をしていただきたいなと、ある程度、その辺はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"ただ漠然と１０年間ということならば、テナントと中にいるお店のそういう話も少しは一部は伺っておりますけれども、公有地をお貸しするわけですよね。その計画が全然見えない以上、これがただ１０年間ということならば、私は賛成はできかねます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"私はちょっと理事者に２点ほど質問したいんですけれども、前回の委員会のときに説明いただいた部分のちょっと改めて確認なんですが。その際、説明をした内容、それをちょっと改めて確認をしたいんです。","respondent":"榎本行財政改革担当課長","answer":"その説明した内容につきましては、当委員会で説明した内容を町会長会議でも説明しましたし、学校などでも、その内容に基づいて説明をしています。ただ、学校を移転、新築することと、その跡地については貸し出すということで説明をしたところです。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"この間伺ったところでは、民間から公有地の活用をしていただきたいという申し出があったときには、それはここがやっぱり大きな前例になるわけです。だから、その辺の基本的な考え方を伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"ある程度その量的なものは充足をしつつ、実際に一番今後長期的に見直した上で、実際に進んでいく方向に少し考えていこうと。これは１つの今回はこういう形のケースですけれども、それはその時々の条件で大分変わってきますので、その中での話になると考えております。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"そうすると、民間に貸し出すことも、これからはケース・バイ・ケースだけれども、そのときの条件によるけれども、あり得るということなんですか。最後の確認ですけれども。","respondent":"榎本行財政改革担当課長","answer":"逆に、その財産については譲渡をするというものも含めて、総合的に判断をせざるを得ないと。当分は出てこないと私は考えておりますけれども、そういうことも含めて、貸し付けをするというのも１つの手段かなと考えております。","id":"exchange-016"},{"speaker":"三上副委員長","kind":"質問","question":"そして、そこのところを借りて、それで品川区の事業を行うということだって過去あったと思うんです。どうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"民有地を借りているところもありますし、国有地を借りているところも今現在もありますので、そういう前提のもとに公の施設等が設置されているところは多々あります。","id":"exchange-017"},{"speaker":"三上副委員長","kind":"質問","question":"ですから、そういった面があって、過去の事例としては、もう少し丁寧にやっぱり説明を理事者側はしなきゃいかんと思います。これは私の意見ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"自民党品川区議団の会派の(2)と(3)はそれぞれほぼ共通するんですけれども、少し教えていただけたらなと思うんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"全く初めてのことですから、その中身は町会、自治体への説明とかが当然入ってくると思われます。ですから、大きな意味で連携という表現をさせていただいたものですから、これと縛りをかけるということではないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"もう少し補足的にお考えを聞かせていただければと思った点が、しながわ自民党の5)の防災拠点としての機能を充実することとありますけれども、どんな防災かとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"本多委員","kind":"意見","question":"例えば防災活動がやりやすいのか、それとも、第一日野小学校が日野中学校跡地に移りますよね。地域で何かあったときに、事が起きたときに対応できるそういうシステムを総合的に視野に入れて、防災機能を上げてほしいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、区の姿勢をお伺いしたいんですけれども、そちらのほうが地域にとって有効だろうと考えたんでしょうか。その辺をちょっとご意見をお知らせください。","respondent":"上野都市開発課長","answer":"その営業継続ということは、そういう地区消費に利用される施設がずっと継続的にあるという意味において、メリットがあると考えています。工事車両の配車とか、こういったものに関しても、近隣に対する影響に対して十分配慮するようにＴＯＣには指導していきたいと考えています。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"１０年間という提示があったわけですけれども、半年間でも騒音、震動は本当にやかましい。つまり、これは精神的また肉体的にもかなりのダメージをこうむると思われるんですけれども、この辺についてどのようにお考えか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"３年とか、４年という時期、そういう点では妥当な計画ではないかと。今の段階ではおおむね１０年ぐらいではないかという程度ですので、当然、極力影響のないように私どもとしても教授してまいりたいと考えています。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"今おっしゃるとおり、本当にそこの地域に与える影響というのは、私もいろいろ調べまして、近隣で商店をやられている方にも話をお聞きしました。区有地を貸すわけですから、そこは十分、できるだけ期間を詰める方向で話し合いを持っていただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"私は先ほどの質問の関係でちょっと改めて伺いたいんですけれども、公有地ですから、近隣の住民の方々中心なんだろうと思うんです。ですから、公有財産で初めての経験ですから、改めてちょっと伺いたいのは。","respondent":"榎本行財政改革担当課長","answer":"ずっと後々影響を引く形になりますので、あとは個別にその都度わかる範囲で詳細なものを説明をしていくという段階に立っていると認識をしております。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"そうしたら、今のところは、もしわかる方がいらしたら、ぜひ教えてほしいと求めました。２点です。","respondent":"新美企画部長","answer":"１点目の三菱マテリアルの件については、直接担当でございませんので、今日はちょっと申しわけありませんが。で、２点目のところ、今のご発言については、特に見解は先ほど申し上げたとおりです。","id":"exchange-027"},{"speaker":"南委員","kind":"意見","question":"１つは、しかし、今までやってきたものとは絶対的に質が違いますよね。したがって、今までやってきたからということでくくって、そういう姿勢は区としても失っていただきたくないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"確認したいんですが、ＴＯＣから１０年から１２年の工事期間という話がここに出ているんですけれども、それは説明が雑駁なところがあったのか、要するに、１０年間絶対にかかりますよという表現で説明があったのかということを教えていただきたいんですが。","respondent":"上野都市開発課長","answer":"さまざまな工夫などもして、おそらくその貸出期間の短縮ということも考慮して検討されるものと考えています。現時点では、まだそういった計画がはっきりしないので、おおむね１０年程度という申し入れがあったということであります。","id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"これはぜひ求めていってくださいということをまずお願いしておきます。もう来年度予算の編成時期に入っているでしょうから、雑駁でいいんですけれども、教えていただければと思うんですがいかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"施設の基本設計という形に入らなくてはいけないということで、１８年度で計上をしないとスタートができないという形になっています。は先ほど都市開発課長からも、全体の計画のスキームが明らかになっていくのだというところで、協議を引き続き図っていくという形です。","id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"質問","question":"基本設計を１８年度中に決めていくということであれば、そのことについてのリミットといいましょうか、それはどういうふうに考えているんでしょうかということを聞けますか。","respondent":"新美企画部長","answer":"大方針として、区としての来年度の予算編成で一方の小学校の設計作業に入るというところが、これがまずスタートとなると考えています。つまり１０年程度と今はなっておりますが、お貸しする方向で詳細計画を詰めてよろしいですよという区側の返事ということになろうかと思います。","id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"確認","question":"それから、民間に貸し出す話の１つで確認なんですけれども、サンピア商店街の裏にある駐車場、あれは品川区所有の土地ですよね。あれはたしかイトーヨーカドー等に貸し出していると思うんですが、その確認をほしいと求めました。","respondent":"岩田まちづくり事業部次長","answer":"普通財産と行政財産と２つありまして、原っぱ公園であった跡地につきましては、まちづくり事業予定地という行政目的をまだ消しておりません。民間に貸し出すことによって、さらに地域のためになる場合も考慮して、さまざまなケースでその都度決めているです。","id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"確認","question":"プラスアルファの新しい事業に取り組んでいくわけですから、どうしても癒着とか、ＴＯＣから行政に対してお金が相当動くでしょう。それを私たちはまとめなきゃいけないですので、その確認だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"ここで生活しているだけの人もいるわけですから、何度も納得できない回答かもしれませんけれども、そこはちょっとご理解願いたいなと思います。空想、こうなる、ただ漠然と１０年間という中で模索して議論するというのは何か不思議な気がいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"伊藤副委員長","kind":"意見","question":"そうすると、先ほど企画部長から説明があったように、これから具体的な計画がどんどん出てくる、その案が提示された中で、ネット・無所属としてこれは賛成できるということになるならば賛成するということですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"願わくば全額求めたいけれども、相手もあることだからそうはいかないという、まだ区としての考えもよくわからない部分があるんです。ちょっと伺いたいんですけれども、２年なのか、そこをちょっと教えていただきたいんですけれども。","respondent":"上野都市開発課長","answer":"おおむねこの方針に沿った形で進めてよろしいですれば、ＴＯＣのほうで大規模改修の計画のあり方についての検討を今後さらに進めていって。それで、そのときに、しかるべき所管委員会でも報告などをするような進め方をさせていただきたいと考えています。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"その詰めの部分も合わせて、大まか１年ぐらいで双方の議論が進む、それぐらいの話し合いの期間を見込んでいるということなんでしょうか。ちょっともう一回教えていただけますか。","respondent":"上野都市開発課長","answer":"協議はずっと並行して進められまして、そういったものの協議は並行して進められるわけですけれども、今の段階で申し上げることはできません。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"２１年度までに４年間ぐらいまだあるわけですから、行政の説明や、それだけの十分な時間がまだやっぱりあるんじゃないのかなと思うんです。仮に１年間それを続けた上で、まだ４年以上あるわけですから、まだ時間的にそこは決まっていないと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"本多委員","kind":"質問","question":"７つの会派で共通する項目があれば、何ていうんですか、報告になるのではないのかなと私は考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"まず１つ言えるのは、その後の問題でも聞くべきではないかと、ここの部分でもそれぞれ一致するところはあるのではないのかなとは思うんです。そういう意見が出ているわけですから、ちょっとるる述べましたけれども、大事な点かなとは思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"本間委員","kind":"質問","question":"非常に前向きなまとめ方のように思います。今の文言は一言も出ていないんですけれども、そのような部分での考え方として、共産党の考えはまとめてよろしいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"防災の問題、具体的に３点ありましたけれども、そこの住民の要望や意見は決してやっぱり無視できない大事な問題だなと考えています。時期的にも、実際あそこが更地になるのは大まか４年後ですから、なおさらまだそういう時間はあるのではないかというのが僕らの見解です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"本間委員","kind":"質問","question":"そしてそこに幼保一元化施設として移る部分もまとまっているんじゃないかと私は受けとめたものですから、今、改めてそのような質問をさせていただいたんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そこがそういう表現になり切れているかどうかは、第一日野小学校を移転していくということについて反対ではないということです。そういうことじゃないかというふうに申し上げたところですから、ぜひそういうふうにさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"大沢委員","kind":"質問","question":"皆さん会派ずつのご意見があるわけですから、第一日野小学校についてはもう皆さんばらけちゃっている部分がある。そこだけちょっと別建てでおまとめ願えないかなということをお願いしておきたいと思います。","respondent":"宮崎委員長","answer":"それは正副でまた議論します。その後の活用をどう考えるのかということが、そういう計画をつくるに当たっての進め方をどうするのかとか、ちょっと意見があれば。","id":"exchange-045"},{"speaker":"西本委員","kind":"意見","question":"当然、その意見の違うところ、考慮をしてほしいところというのはいろいろ出ていると思うんです。それから、それで添付するという形が一番いいんじゃないかなと思うんですが、そういう形でまとめていただいたらいいんじゃないかなと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"南委員","kind":"意見","question":"西本委員のおっしゃったことも、論点をもっとはっきりさせて、そこでどんな意見が出たかということでまとめていただいていいんじゃないかと思います。それは正副にお任せしてやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"須貝委員","kind":"提案","question":"先ほど本多委員からご提案があったんですけれども、ほとんど各会派をまとめるとしても、現実論、これはなかなか難しいのかなと。どういうふうにまとめられるかわからないですけれども、このまま使えるなら、このまま出したほうがいいんじゃないかなと思いますとの意見を述べました。","respondent":"宮崎委員長","answer":"今、皆さんに今後のまとめ方等、委員会としての取り組みの意見もいただきました。","id":"exchange-048"}]},{"id":"topic-02","title":"密集住宅市街地整備促進事業、二葉３・４丁目、西大井６丁目の地区防災まちづくり計画（案）説明会等について","agenda":"密集住宅市街地整備促進事業、二葉３・４丁目、西大井６丁目の地区防災まちづくり計画（案）説明会等について","exchanges":[{"speaker":"本間委員","kind":"意見","question":"いわゆる二葉４丁目付近ですが、この防災まちづくり計画案の概要の中の「道路について」３項目に、電柱が残っている部分がございましたね。その件について、ただ建て替えでセットバックしてもらったけれども、電柱がそのまま残っているという部分についてのお考えをお尋ねしますとの意見を述べました。","respondent":"伊勢住環境整備担当課長","answer":"道路拡幅したにもかかわらず、電柱がかなり出っ張っているところにつきましては、東京電力に働きかけをしていくというような考えを持っています。電柱の設置者であります東京電力だとか、事業が進む中で個別にやっていきたいと、こういうふうに考えてあります。","id":"exchange-049"},{"speaker":"本間委員","kind":"質問","question":"時機を逸したらなかなかというようなことにもなろうかと思いますし、それは個々のケースでいろいろあるかもわかりませんけれども、事前にそういうふうな申し出がある場合には対応できるんか尋ねました。","respondent":"伊勢住環境整備担当課長、松代管理工事課長","answer":"設置者が移転しないことにはどうしようもないわけですので、そういう面では積極的にこの事業の説明を十分して、設置者に対して理解を求めて。道路を管理しています管理者という、そういった立場からですが、占用地に送電柱、またＮＴＴ柱等々があります。","id":"exchange-050"},{"speaker":"本間委員","kind":"質問","question":"そうしていただければいいんですが、そうすると、その本人の、あるいは対象となる家の申し出によって、そういう希望が生じた場合には、対応をしていくということでよろしいんか尋ねました。","respondent":"松代管理工事課長","answer":"周辺のところに１軒１軒当たりまして、そういう調整等は占用者がきちんと地元に当たりましてつけていくと、こういったことで指導してまいります。","id":"exchange-051"},{"speaker":"本間委員","kind":"質問・要望","question":"せっかくこういう事業をやるわけですから、なかなか後々のことにも地域に理解を求める困難性が生じてくる場合がありますので、その辺は今後きちんと進めていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"本多委員","kind":"質問・要望","question":"４番目の補助２９号線の整備を関係部局に働きかけるというところで、昭和２０年代、非常にまざった計画ではないのかなと。３年前に２９号線の見直しを求める請願が区議会全会派で採択されている経緯もありますし、その辺をちょっと確認をさせていただきたいんです。","respondent":"伊勢住環境整備担当課長","answer":"やはり密集事業を進めていく中で、請願の話と、この空間が非常に防災性の観点からは重要な空間になっておりますというような説明をしております。","id":"exchange-053"},{"speaker":"本多委員","kind":"質問・要望","question":"これからの１０年間とかというプランでも都のほうで全く手をつけませんよということになっちゃっているんですが、この関係部局に働きかけるというのは具体的にどういうことなのか、ちょっともう一度教えていただきたい。","respondent":"伊勢住環境整備担当課長","answer":"それから、道路という形で整備するというのはもちろんそういうことなんですが、一定の空間として整備できないかということも、今、研究しています。ですから、東京都がやるということであれば、そちらのほうに働きかけをするというような考えでおります。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっともう一度、それで、どれくらい拡幅されるのかというのをちょっと確認の意味でもう一回教えてほしいと求めました。そういう住民の方たちの思いというのを受けとめながら判断していく必要があると思うので、ぜひ、どうなっているのかを教えてほしいと求めました。","respondent":"伊勢住環境整備担当課長","answer":"６メートル確保というのは必要ですという意味を我々からも十分説明をいたしまして、ご理解を得た上、こうやって載せてあります。２９号線につきましても、皆さんのご理解といいますか、説明した上で載せております。","id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"２９号線を整備して延焼遮断帯をつくる以外に、何か方法というのは考えられないんでしょうか。ほかに方策がないのかなということをいろいろな角度から検証されてなのかなとも思うんですけれども、ちょっと改めてその辺も紹介してください。","respondent":"伊勢住環境整備担当課長","answer":"まさに今説明しましたこの計画図案あるいは概要に載っているものがそのものです。申しわけございません。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"そうしたら、その辺の数字を、どのくらいの住民の方々がおられるのかがわかったら、後ででいいですけれども、教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"これで承認が得られると、ある程度の補助金とかというのが出てくるのか、その辺はいかがでしょうか。たまたま建て替え時期に来たからという人はよろしいかもしれないんですけれども、その辺の財源も含めた計画はどうなっているんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"それともう１点、１０年間の事業期間ですけれども、なかなか難しいのではないかということで、そのとおりです。もっとも、最近建てたという方は、当然１０年間の中ではおさまりませんので、その辺は難しいだろうということが挙げられます。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"安全面も含めて公園緑地をつくっていただきたいなというふうに、これは要望になると思うんですが、考慮していただきたいと考えています。ある程度促進をして、何かしらのお金が出る、補助金が出るという考えでよろしいか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"少なくとも、短い辺が１０メートル以上ということで、それだけあれば防災性が高まるというふうにされてあります。その補助金対象の２分の１が国で、４分の１、４分の１が区と東京都というような財源の内訳です。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"要望なんですが、先ほど１００平米以上ということなんですが、やはり死角になりやすい部分があるんです。そういう周りの環境でどういう広場になっているのかというのは、それを考慮して計画をしていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めてちょっと伺いたいのは、まちづくり協議会の活動や、この密集事業において、住民参加で住民合意のこの位置づけを品川区がどう考えているのか、改めてちょっと教えていただきたいんです。","respondent":"伊勢住環境整備担当課長","answer":"この密集事業につきましては、品川区が推進している事業ということで、基本は品川区が計画を立てて、それで大臣承認等をもらって計画を進めるです。こういうものを設置してきたということで、そういう方のご参加を得ながら進めていっていると、こういうような状況です。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"これのこれまでの経過を伺っていますと、６丁目のほうが９月までは準備会で、１０月からは懇談会という形で２回ですよね。住民の懇談会を持って進めていくというところが、それがよくわからないので、もう一度説明いただけますか。","respondent":"伊勢住環境整備担当課長","answer":"やはりこの趣旨を十分説明した上、趣旨を十分説明した上、たたき台の検討だとか。特に貯水槽の関係、こちらについては非常に必要性を認識されていますので、その辺の話が中心になった懇談会の内容でございました。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"なぜこの事業が必要なのか、なぜ防災の広場だけでない貯水槽や、いろいろ議論を重ねて１３回やってきたわけですよね。ここはもう一度伺いたいんですけれども、３町会が一体となった１つの事業として成立しているのかなというのがちょっと気になるので、もう一度。","respondent":"伊勢住環境整備担当課長","answer":"そういう認識の若干意識のずれがございましたので遅くなったわけなんですが、決して不十分な態勢での密集事業の開始ということではございません。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜでしょうかね。３・４丁目の方と西大井６丁目のこの地区として１つの計画ですから、丁寧な進め方が必要ではないのかなとは思っているんです。","respondent":"伊勢住環境整備担当課長","answer":"したがいまして、３カ所ありますけれども、その３カ所が３カ所、個別に事業を開始した後、働きかけをしていくわけです。４月に予定どおりこの事業が開始した後も、変更すべきものが出てきた場合には、それを考えていくというような腹づもりでおります。","id":"exchange-064"},{"speaker":"南委員","kind":"質問・要望","question":"これをちょっと詳しく教えていただきたいのと、ちょっと私は理解できなかったので、任意事業として進めるというふうな説明をされましたよね。その任意事業というのはどういうものなのか、そこを説明を求めました。","respondent":"伊勢住環境整備担当課長","answer":"大臣承認あるいは同意というのは、これは品川区で密集事業と言っただけでは財源の確保はできません。６メートルに拡幅する場合に、いろいろなケースがあると思うんですけれども、その土地を任意で買収するというようなことです。","id":"exchange-065"},{"speaker":"南委員","kind":"確認","question":"それから最後にちょっと確認なんですが、確認としては、そして今回の説明会があるんだということなんですか。最終的に、少なくともまちづくり協議会の皆さんの理解と合意は得られたという確認をしているということか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"今の合意というようなことですけれども、この内容を懇談会で事前に１１月にそれぞれ西大井と二葉で出して、これを確認して日程を決定している。","id":"exchange-066"},{"speaker":"須貝委員","kind":"意見","question":"その道路に面している１軒１軒の方たちだと思うんですけれども、町会の役員が１軒１軒手渡して、ちょっとその辺だけ聞かせてくださいとの意見を述べました。","respondent":"伊勢住環境整備担当課長","answer":"はこちらをお配りして、お集まりいただいて、事業の説明を十分することで拡幅を十分理解していただくということです。ここが建物がかかっていると、測量はしていないですから正確なことは言えませんけれども、あまり個別の説明はこの日はしない予定です。","id":"exchange-067"},{"speaker":"宮崎委員長","kind":"質問","question":"三伺いたいんですけれども、やってくださいということでやっていくのかどうか、ここも大体何軒ぐらいが対象になってくるのかというのはわかりますか。","respondent":"伊勢住環境整備担当課長","answer":"進め方ですけれども、消防活動困難区域を控えていますので、ぜひご協力を仰ぎながら進めていくと。協力いただくという面では全く同じものです。","id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664767?Template=document&Id=6314#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":52124,"voices":130}},{"id":"h17-20051201-14","meetingId":"h17-cm12","date":"2005年12月1日","dateIso":"2005-12-01","committee":"行財政改革特別委員会","time":"午前１０時０７分～午後２時２７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件整理しています。","topics":[{"id":"topic-01","title":"行財政改革に関することのうち、民間委託等に関すること","agenda":"行財政改革に関することのうち、民間委託等に関すること","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"具体的に指定管理者の候補者を選ぶ段階で、どういう周知をしているか。これから民間やＮＰＯまで広げていこうとすると、どういう公募をするのか教えてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"今後、公募する場合につきましては、候補者を実際に選ぶ段階でホームページ等を使ってやっていきますけれども、今回は基本方針に定めたとおり、現行事業者を基本としていくということで、今回については特に周知という形はとっておりません。","id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"その上で審査をして、選定をして決めるという格好になるわけですね。もう１つ聞きたいのは、なぜ今まで庁内でやっていたものを議決をするというふうになったのか、考え方について説明願いたいんですけどとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"それに対応するように、逆に指定管理者の指定に関しては、議会の関与という形で入ってきております。もう１つは指定の議決ということで、例えば工事の請負契約ですとか、そういう形と同一の趣旨だと考えております。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"その辺はいかがでしょうか。先ほどの私の質問に、なぜ今度新たに指定管理者制度の中で議会の議決をするようになったのか、もう少し説明をほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"要は公の施設の設置者としての責任が自治体にあって、運営上の責任は指定管理者にある。それは契約案件も同じですけれども、そこでこの制度の適正さを保つという形のしくみになっております。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"本来行政がやるべきものを民間企業やＮＰＯまで拡大した場合に、先ほど基準の中で、サービスの向上と経費の節減と２つの柱を挙げた。検討ができるような資料を出すべきだと思いますけれども、そこはいかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"議会のチェックという部分ですけれども、契約議案と同じような形でのきちんとチェックできるものをお出ししていると考えています。今回は基本方針のもとで、各選定理由等の中にも、それぞれの今までの実績等を踏まえた選定理由ということで説明をさせていただいたという形です。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"それを議会がどう審査したのだということは、私は今までの形どおりではなくて、必要な資料を出していただきたい。これは後ほど論議になると思いますけれども、いろいろな問題で不十分な点があるということを、飯沼委員の方から述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"選定委員会において５段階評価と総合的な評価を行い、家庭あんしんセンターのところで、選考基準というのが４項目に分かれて書かれているんですね。この資料からすると、資料提供があって初めて議会が行政と対等な意味での評価ができると思うんですけれども、この辺についてはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、ぜひこの辺を今日この場でも論議をしていただきたいなと思います。私はどういう分担をするのかという大前提に、同じ情報が得られていなければ、ぜひこの場でこの点も論議をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"藤田委員","kind":"質問・要望","question":"その中の運営については、これは区が設置者ですので、区と任された指定管理業者との間は綿密にやっていただかなければいけないと私は思うんです。住民サービスがいろいろな不満とか要望とかがあって、これまでは区に対してそういう要望を上げてきたわけですが、それでよろしいんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"基本方針の方で述べましたように、一番のねらいは満足度の高いサービスを提供するというためにまず趣旨としてある。設置責任者としての区はフォローなりカバーをしていくという形で、そのしくみの部分というのは継続していきますし、工夫を図っていくというものです。","id":"exchange-008"},{"speaker":"藤田委員","kind":"質問・要望","question":"それともう１つは、こうしてもらいたいんだという要望ですよね。利用者は管理者に対して要望を直接言っていくのか、区の方に言うのか、それとも両方へ言わなきゃいけないのか、この辺をお願いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"そういうサービスの部分につきましては、第一義的に管理者の方に言えば、それが区に伝わるという形での管理をしていくというのが大前提です。どう次の計画に改善して盛り込まれるかというものをしくみとして入れ込んでいくという形を、今後工夫を図っていきたいです。","id":"exchange-009"},{"speaker":"藤田委員","kind":"意見","question":"これはやっぱり１つの大事なチェック機関だと私は思うんですが、我々はそこで議論していくと、このようになっていくと私は思うんですね。これは意見ですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"確認","question":"最初にちょっと、説明文の中でよくわからないところだけ確認をしたいと思いますけれども、今も料金はいただいている部分があるでしょう。この４文字だけではちょっとわからないので、詳しく説明ください。","respondent":"榎本行財政改革担当課長","answer":"この利用料金制というのは、例えば区民集会所の施設使用料を考えますと、施設の使用料として区が歳入をするというのが普通の使用料の歳入だと。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"確認","question":"これからのことを確認していきたいんですけど、今の料金の場合も、我々に予算案が提示されて、予算を決めていきますよね。業者の方は４月１日からやりたいのにできないという、そういうことについてはどういう検討をされてきているのか、それだけ説明ください。","respondent":"榎本行財政改革担当課長","answer":"そもそも条例の枠組みを変えるような形であれば、条例の改正を待ってという形になりますので、そういう手続が必要かと思います。実際に料金を変えるのは大体３カ月もしくは６カ月程度の経過措置を置いた後で変えるというのが、その間で対応していくという形になると思います。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"だから、１年ごとに評価をしていったときに、翌年どうするかというのがきちんとわからないんだよね。１年ごとに、ちょっと例えはいいかどうかわからないけど、月次はどういうふうにこの業者の人たちはやっていくわけか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"条例に基づいた枠内という形になりますので、そもそも指定管理者側が条例に違反するような料金設定はできない形の枠組みになっております。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"区の施策をそっくり丸投げしているかのように受け取れるんだけれども、もうこれはこの業者に任せるんですか、こういうことは。この管理者への要望というのか、そういうこととの折り合いというか、そういうことについて聞かせてください。","respondent":"榎本行財政改革担当課長","answer":"要は政策目的があった、それの手段としてこういう施設を置いてやっている。それ以外にも障害者のいろいろな就労支援とか、課題としての事業者の認識の部分という形での表記です。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"こういう区の施策があって、それに積極的に取り組んできてほしい。そういう要望的なものなら構わないけれども、区の施策まで移譲しちゃうみたいなところが見えるんだけど、そのように見ちゃいけないんですかね。","respondent":"新美企画部長","answer":"委員ご指摘のように、もう一度福祉高齢事業部にも確認をして、区民へこういう結果について公表する場合は適切な表現をしてまいりたいと思います。決してそのまま任せっきりということではございませんので、ご理解いただきたいと思います。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"その辺をどうこれからとらえていくのか。来年も１件ある、あるいは５年という先の話で申しわけないけれども、その考え方をお願いします。","respondent":"榎本行財政改革担当課長","answer":"実際上、今までこういう管理していたものを、新たにやる場合にはどうなるかという提案を受けるというのが原則になろうかと思います。その点は十分競争条件が公平になるような形での部分というのは、今後それぞれ導入する中での検討として、十分配慮していきたいと考えております。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"意見","question":"それが年度末ならまだあれだけど、例えば８月とか９月とか、年度の途中で事件が起きた。そういうことも協定を結ぶときに、最悪の事態も計算してやっておくべきだと思うんだけれども、その辺の考え方を最後に聞かせてくださいとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"指示をして、それでもできない場合には取り消しをするというような、法的な手続としてはそのような形で想定をしております。その中で、業務の引き継ぎ等もこの協定書の中に入れまして、そういう事態も想定した上での協定書の具体的な作成という形を考えております。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"前から聞こうと思って確認したかどうかなんですけど、１年度の３月いっぱいですね、基本的な考え方として。例えば３年後の、２年半ぐらい先の話になってくるのか、中身ではなく時期的なもので。","respondent":"榎本行財政改革担当課長","answer":"５年を基本として考えますと、大体第４定例会のときには指定の議決をして、それから協定の準備という形のスケジュールになろうと思います。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１つ、先ほどの質問の中で、果たしてその声が区の方へ伝わってくるのかなというところに非常に疑問を感じるんですよね。指定を受けているかたはどうしたって出さないんじゃないかなというのを非常に感じるので、今、ちょっと２点お願いします。","respondent":"榎本行財政改革担当課長","answer":"実際上、ずっと継続してやってきたという制度になっていますので、今回初めて期限を切った管理委託という形になってあります。予防等も、直接それぞれの施設という形であれば来ておりますので、そういうものもきちんと検討しながらという形でいきたいと思います。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ一番問題なのは、もう４月からここからいなくなるんだよというと、どうしてもそこら辺に影響を及ぼしてくる部分が起きると思うんですね。今からその辺を十分意識した形の締結をしておいていただきたいなというのを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問・要望","question":"今の鈴木委員と同じ質問があったんですが、今の内容で少し確認できたんですけれども、この「等」というのはほかにどういったものがあるのかなと。そこら辺のところをもうちょっと詳しく、どういうしくみでこのモニタリングのしくみができているのか、教えてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"ここの事業報告書等の部分ですけれども、この事業報告書そのものにつきましては、法律で年１回が義務づけられております。その部分で、クレームなりをきちんと情報を共有して、その施設ごとに一番適した形でのモニタリング等の仕組みをつくっていきたいという形です。","id":"exchange-021"},{"speaker":"中島委員","kind":"質問","question":"民間ですから、そういったことが利用者にとってマイナス面が出てきてはいけないなということが１つ心配な点なんですね。こういう方たちの声がすっと通るような、反映されるような窓口みたいなものは、区としては設定されるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"ここにつきましては、どういう職員配置をして運営するのかという形をきちんと決めてまいりますので、その中で対応を図っていきたいと思います。実際上、どういうふうにその苦情等を集約して、きちんと対応していくかというものをつくり上げていきたいと考えております。","id":"exchange-022"},{"speaker":"中島委員","kind":"質問・要望","question":"人間同士のふれあいというんですか。ですから、その辺のところまで区はしっかり関与して見ていかなくてはいけないと思うんですが、その辺をお答えほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"今、それともかえなくていいのかという、最初の競争をさせるのかさせないのかというところに一番直結してくる問題だと思います。その中で総合的に判断した上で、そうじゃない場合も十分あり得ますので、その辺は事業の実績等を踏まえて総合的に判断していく必要があると思います。","id":"exchange-023"},{"speaker":"中島委員","kind":"質問・要望","question":"その視点でしっかり業者を選ぶという区の資料をとってほしいと求めましたし、その中で議会としての責任を持った判断をしていきたいと思いますので、その点でもよろしくお願いしたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"築舘委員","kind":"質問・要望","question":"責任があるわけですから、その報告が上げにくいという、直接の監査ができにくいということがあるわけですよ。今度指定管理者制度になったら、それは議会から監査委員として２人出ているから、その辺のことを聞かせてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"逆にいくと、その施設を受託している範囲内で監査を実施できるという形がきちんと自治法に明記されておりますので、その中でやっていく。今回の施設だけで６０施設ありますので、監査委員の方の体制等もありますので、その中で適切に対応していくというふうに思っております。","id":"exchange-025"},{"speaker":"築舘委員","kind":"質問・要望","question":"指定管理者制度という民間の事業者の能力やノウハウを活用するというせっかくいい試みをしようとしているわけですから、実際に内容を充実させるべく、単なる表面的なきれいごとに終わらないようにお願いしたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"三村委員","kind":"質問","question":"３ページの事業報告書等のところで、チェックの評価の中に実際に現場の職員の方たちが足を運んで現場を見るようなしくみづくりも現在考えているのか、その辺についてお伺いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"いろいろな検討の中では、実際に会議なり打ち合わせなりをするという方法も検討できますし、そういう中で工夫を図っていきたいと考えております。","id":"exchange-027"},{"speaker":"三村委員","kind":"質問","question":"総務ですとか企画の方が入られるということだったんですけれども、どうしても行政の場合、人事異動がありますよね。そういったあたりの評価の精度をどのように一定レベルに保っていくのか、その辺についてどのようにお考えなのかお伺いをいたします。","respondent":"榎本行財政改革担当課長","answer":"実際、やはり専門的な分野というのは私も全部知っているわけではありませんので、その部分での審査というのを主に受け持たせていただいております。","id":"exchange-028"},{"speaker":"三村委員","kind":"質問・要望","question":"今までいろいろ顔をつないで、区役所の方と顔の見える関係になっても、人がかわると全く情報が引き継がれていない。ぜひそういう情報の共有等も図っていただきたいということ、情報を持っている方、要望して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"情報公開の点でちょっとお伺いをしたいんですが、その点を改めてお伺いしたいのと、人の配置がすごく影響する事業が多いと思うんですね。この辺において、例えば人件費の中身の公開がされるのかどうか、ちょっとその辺をお伺いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"情報公開制度の場合には、そういう情報公開を求めてきた場合についての対策までも考えた上で、実際上対応をとらなきゃいけないと考えております。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"例えば資料を出す前段階での確認というか、あと情報公開制度で求められている中身の資料が、より広く公開されるべきであると思っているんですね。ちょっとその点が品川区の場合はどうなのかなと伺うんですけれども、情報公開制度の、区が持っている制度の対象としていく。","respondent":"榎本行財政改革担当課長","answer":"プロポーザルに当たって企業ノウハウをどういうふうに説明してもらうか、要は別つづりにする等の工夫を図ることができるのかなと考えております。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"意見","question":"その両方できちんとしていかないと、この辺は担保できないんじゃないかと思っているんです。その中に、両方にきちんと明記をしながら公開をさせていくというぐらいの歯どめがないといけないんじゃないかと思っているんですが、これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"武内委員","kind":"質問","question":"プレゼンテーションというんですか、意気込みというんですかね、そういったものをお聞きする場を設けていらっしゃるのかどうか。","respondent":"榎本行財政改革担当課長","answer":"今回、選定委員会の中でそういうプレゼンテーションを受けたのは、区営住宅、区民住宅の管理者は民間事業者ですので、その３者についてはそういうプレゼンテーションというのを行った上で選定の審査に入ったという形です。","id":"exchange-033"},{"speaker":"武内委員","kind":"提案","question":"例えば大ホールが今まで１日１コマしか入らなかったところを、今度検討してそうじゃないようにするんだとか、いろいろなご提案があったんですね。","respondent":"榎本行財政改革担当課長","answer":"今回の施設の利用のサービス向上について大きく変更があったところは体育館ですね。その他につきましては、細かいところはありますけれども、大きな枠組みとしては、そのような変更というのはなかったと記憶しております。","id":"exchange-034"},{"speaker":"武内委員","kind":"質問・要望","question":"そうした意欲ですとか取り組みに対してのそういうものを聞く場をぜひ設けていただきたいという要望と、その間に、公募された中で幾つか応募があると。もしくは区民かどうかわかりませんけど、それとも第４定例会の議会に上程されるまでそういったことをお知らせしないのか、どうなるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"公募する場合につきましては、まず公募要項を発表する前の段階で議会等に報告をして、これからこういう事業者、こういう施設に対して公募を行いますという報告をした上で、それぞれ手続に入っていきたいと考えております。","id":"exchange-035"},{"speaker":"武内委員","kind":"意見","question":"それでその応募状況ですね。それをどういう形でお知らせするのか、時期的なものも含めてとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"適宜公募要項を出しますと全体のスケジュールが見えますので、その締め切りの後、必要な時期に応募状況等はご報告できると思います。その中で最終的には指定議決のときに説明等はしますけれども、随時その途中経過でのお知らせというのはするようにしていきたいと考えております。","id":"exchange-036"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。できればその前にどういった業者が応募されているんだというのがわかれば、先ほど情報公開がありましたけど、その方向でぜひ要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"私は議会で議決をするに当たってどういう審査をすべきかという点で先ほども質問したんですけど、それから選出過程で作成される文書はどんなものがあるのか、説明願いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"その基本方針策定に当たりましては、特にその資料等、例えば事業計画書等の資料で具体的なことを選定したという形ではございません。各事業部の中でどういう形で指定管理者制度に臨むのかというもの随時ヒアリングをしながら、最終的な区としての方針を固めてきた経緯です。","id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"このうち議会に示すべき資料は何と何なんでしょうか。それから、概要だけれども議事録はつくっておりますという話だったんですが、これは議会に資料として提出していただけるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"ですから、そこの中から必要なところを抜いた形でのある程度まとめたものという形で議会には示すべきだろうと考えております。議事録につきましては議事要旨という形でまとめておりますけれども、それは議会側からの要望等があれば出すという形は可能と考えております。","id":"exchange-039"},{"speaker":"沢田委員","kind":"質問・要望","question":"企業秘密にかかわるから出せないといった答弁があったそうですけれども、私はおそらく委託料の７割から８割は人件費だと思うんです。もちろん出していい資料、もっとオープンに議会を信用して出していただきたいということだけ述べて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"大西委員","kind":"確認","question":"建築確認等でいろいろな問題が起こっているということをご承知だと思うんですけれども、これに関しては民間が建築確認をおろしていろいろな問題が発生してきているということですけれども、どのような認識でおられるのか。","respondent":"榎本行財政改革担当課長","answer":"この公の施設の設置者である区が責任を負うという形になります。要はあくまでも設置をしたのは区で、その執行がうまくいくのかいかないのかという部分の責任というのは区が負うという形になります。","id":"exchange-041"},{"speaker":"大西委員","kind":"質問","question":"どういう点が一体すぐれているのかとか、どういう意欲があるのかとか、そういう点が全くわからない。このヒアリングの内容を区が掌握しているわけですから、できない等、この部分に関してはどうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"基本方針の中で審議は非公開という形をしておりまして、そういう説明等が受けられなくなるという可能性があるという形で、そういう形をとっているところです。","id":"exchange-042"},{"speaker":"大西委員","kind":"質問","question":"３年間とやっていけば、いずれそのノウハウを出してやるわけですから、それがその場で非公開であって何か意味があるのかなと。それを非公開することに意味があるのかなと思うんですが。","respondent":"榎本行財政改革担当課長","answer":"その中の質疑の中で、これは具体的にどういうことなのかという形の説明等をしていくという形で対応するものと考えております。ノウハウを書くとここの団体は全部外へ出るので、そういうノウハウは書かないで、口頭だけで説明をしていこうという形になりますので。","id":"exchange-043"},{"speaker":"大西委員","kind":"質問・要望","question":"先ほどの中で責任が区に帰属するですので、もう少し私どもが議決するに関しましては、中身がより理解できるような資料の提出を今後望みます。これは要望としてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"三村委員","kind":"提案","question":"各事業者がそれは企業ノウハウだということで共有化できないということは、利用者にとっては多分マイナスになってくると思うんですね。なるべく提案内容と指定管理者のその後のノウハウということで違うと思うんですけれども、提案内容をどこまで出すかというだけじゃなくてとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"その部分については競争する上での前提になりますので、そこのルールづくりはきちんとしておかないと、その競争状態というものが保てないと考えております。","id":"exchange-045"},{"speaker":"林（宏）委員","kind":"提案","question":"９月まであるわけですから、品川区が提案して５区でこういう制度というのも可能性としてはあるわけで、あるいは具体的にもう決まっているならそういう主なところを出していただけますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"今後指定管理者制度導入をする施設の予定ですけれども、それからあと想定として挙げておりますのが品川と荏原の健康センター。業務分析とか業務の内容を確認したところ、それを指定管理者にかえることによってノウハウの部分ができるかというところを検討したんですけれども。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"意見","question":"議会全体がどういうふうにというのはわかりませんけれども、政策評価というのは、あくまでも行政の立場に立ってしていくものです。委員長の突然に向かって、また突然に輪をかけたみたいな話で申しわけないんですけど、僕自身はそう思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]},{"id":"topic-02","title":"議員定数に関すること","agenda":"議員定数に関すること","exchanges":[{"speaker":"中島委員","kind":"質問・要望","question":"そうした方たちがいろいろ区政に対しての要望なんかも届けてくださる、こういうことも現実にあります。皆さんのご意見、そしていろいろ自分たちで調査したことを考え合わせまして、３８名という数をご提示いたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"大西委員","kind":"意見","question":"北区では３３万人、私どもより少し少ないわけですけど、法定定数は４６名ですが、４４名で２減のままの状態であると。それで品川区が議員を減らさなくてはならないという議論が私どもではなされないですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"沢田委員","kind":"提案","question":"我が会派ならこうやるという要望を、我が会派はこれを提案したいということをやれば政治はずっとよくなると思いますし、議会費は８億円ですけれども。ですから、私は定数を現状よりの減については反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"築舘委員","kind":"質問","question":"ですから、人数のことに関しても、退職不補充ということで減らしていくという努力をしているわけです。それじゃずっといいのかということになるわけですから、各２３区を見ますと、２３区はほとんど減らす状況に来ております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"２つの数字が出てきましたけれども、数字では相いれないという意見になるわけですから、どういうところで最終的な結論を得るというふうに持っていく。先ほど来出ている４０名とか３８名とか４２名とか、そういう数字が適切であるという根拠が見当たらないわけですから、そういうような決め方ですから。","respondent":"須藤委員長","answer":"一通りご意見をいただきましてから、進め方については対応していきたいと思います。続きまして無所属の会。","id":"exchange-052"},{"speaker":"三村委員","kind":"意見","question":"理由といたしましては、議会としてどうやって多様な民意を反映させていくか、そういった視点が定数を考えていく上では一番重要かと考えております。","respondent":"須藤委員長","answer":"今、林委員から今後の進め方について１つの方向性を出さなければ、次に進めないんじゃないかというお話をいただきました。委員会のあり方、進め方についてご意見等がございましたら、ご発言を願いたいと思います。","id":"exchange-053"},{"speaker":"藤田委員","kind":"意見","question":"当委員会として、とりあえず削減するのか、現状維持でいくのかというこの２つが大きな別れ道になっているのではないかなと。１になるのか、２になるのか、３になるのか、４になるのか、これはわかりませんけれども、そういう諮り方でお願いできないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"林（宏）委員","kind":"提案","question":"その前にどういう手順で議長に上げて提案をしていくのかというのも諮っておかないといけないと思うんですよ。ですから、４と我々の任期の行財政改革特別委員会というのがあるわけですから、僕はそういう流れをつくっていかなきゃと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"沢田委員","kind":"提案","question":"むしろ今、削減をすると提案を出された方に聞いてみたいことがあるんですけれども、そちらの議論に進んじゃっていいかどうかですね。なぜ削減を、２あるいは４を提案をしたのかということについて聞きたいんですが、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"藤田委員","kind":"質問","question":"私はその中で言っていることは十分だと思うんですけれども。１年前には、それぞれ次に立候補したいという方もいらっしゃるわけですから、私は親切ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大西委員","kind":"意見","question":"今、削減するとどういうデメリットが発生するのかということまで踏み込んで、私たち議員は議論しなくてはいけないんじゃないか。そうなると、これは軽々に議員定数削減ということのみで話していくことには、私は強い危機感を覚えるところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"沢田委員","kind":"意見","question":"それは他区がやっていなくたってやるべきことはやるのであって、右へならえするなんていうのはおよそ論議としては理解できないですね。そういうことを主張するというのはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"沢田委員","kind":"意見","question":"私は注意して言ったつもりなんですけど、前段の助走部分ではかなりやってきた。いわゆる核心に入ったのは２回という意味で、その前にずっと調査してきたということまで否定してはおりませんので、ご理解をお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"中島委員","kind":"質問・要望","question":"じゃ、そこの問題が起きたようなところの行政は、果たして議員の定数はどうなんでしょうかということも知りたいなという疑問があります。じゃあ、住民の方のお声の中には、今、現状の議員がすべて１００％住民の声をきちんと反映している議員なのかどうか、こういった質問もありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"沢田委員","kind":"確認","question":"イーホームズの建築確認審査機関のチェック機関と言ったのは、民間の確認検査機関そのもののチェック機能が働かなかったという意味で私は言ったので。ですから、例の歴史教科書の問題で自虐的だというふうに言ったけど、まさに立法機関として自虐的だと思いますね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"武内委員","kind":"質問","question":"葛飾区に問いあわせて葛飾の区議会議員にお聞きした際には、なぜこんなに一気に減ったんですかというお話を聞いたんですね。これを葛飾に当てはめると葛飾の法定定数が４６ですから、それにこれを掛けるとどうなるか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"築舘委員","kind":"質問","question":"数を極端に減らすことによって質の向上はどうなるんだという議論もあるわけですから、ただ単に減らせばいい、多く減らせばいいということではない。人口も増えていることですから、何も改革だから即２だという単純なことではないわけでありまして、削減の方向にしていかなければいけない。","respondent":"須藤委員長","answer":"議員定数に関することは議会運営委員会でこの特別委員会をつくられて１つのテーマになったので、林委員、その考え方でよろしゅうありますか。先ほど全員協議会云々という考え方があったんですけれども。","id":"exchange-064"},{"speaker":"林（宏）委員","kind":"提案","question":"こういう改正案を出してくださいという提案をするのか、よくある委員会としての提案として、賛成の人の名前で議員立法という形をとっていくのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"沢田委員","kind":"意見","question":"それから、以前３０万人を下回った場合には議員定数問題を考えるということを一度議決しているんですね。今、それから時間がたってどういう状況の変化で３０万人を下回っていない、私は必要なんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"沢田委員","kind":"提案","question":"たしか鎌田前議員だと思うんですけれども、条例提案でそのことを言ったんですね。だけど区民の要望は議会は議会らしく本来の任務を果たしてくれ、議会制民主主義は根底から瓦解すると思いますねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"林（宏）委員","kind":"質問","question":"その最終的な自分たちの意見を出すところの参考にしていきたいということですから、例えばここでこの委員会は削減の方向を決めます。１つそれをやって、そういう道筋がいいのかなと、僕はそう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"大西委員","kind":"意見","question":"だから減として私たちはどうこうするということに至っていなくて、現実的には議員定数を１つも減らしていない区もたくさんある。私たちは既に４６名から４２名という形で汗を流しているんです、血を流しているんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"大西委員","kind":"質問","question":"あなたはどこにお住まいなんですか。ほかの議員に尋ねたんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中島委員","kind":"意見","question":"それともう１点、街頭演説をやっているだけが議員の仕事ではないと思います。そうではなくて、さまざまな区民の方の声を反映できていると自負を持っているところでありますので、今のご意見に対して一言申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"提案","question":"この間、他都市の状況で少しでもいい施策があったらば持ってきて提案するとか、やることはまだまだあると私は思っているんです。議会がどうあるべきかというところを、今持っている力をもっと発揮していくような方向での議論ができたらいいのではないかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"三村委員","kind":"質問・要望","question":"一度方向性をつけない状態で全員協議会を開いて、その上でさらにこちらの委員会の方に持ち帰って議論していっていただきたいなと思っています。きちんと議会として民意をどういうふうに反映させていくべきか、議会をどういうふうに活性化させていくべきか、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"武内委員","kind":"質問・要望","question":"今日結論云々ということじゃなくて、今日は人数ということだけお聞きしていますので、どこかの段階でそういう方向性を確認できる結論をとるべきだと。それも１つの方法だと思いますけど、間に合うような形で方向性を決をとっていただきたいと、意見として思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"沢田委員","kind":"提案","question":"それを含めて意見交換をして、それをもって最終的に当委員会でどうするのかという決着の手順がいいところなんじゃないかと。全員協議会までに減とかどうとかと決めておかないで、とりあえずやろうという提案は私は賛成ですので、した方がいいんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"藤田委員","kind":"質問・要望","question":"大学の先生にも２回ほど来てもらい、３回ですか、１回かな。ですから、これは結論的には正副委員長で話し合って、どういうふうに結論するのかわかりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"大西委員","kind":"質問","question":"私に尋ねてきている人たちに、演説している人がいないんですかということを申し上げたんじゃないので、ちょっとその解釈をしっかりしてほしいのと。だから、そこにおいて議員定数がどうあるべきだ、こうあるべきだという議論が昨年１年間なされていないんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"中島委員","kind":"質問・要望","question":"何でこれまでやってこなかったんですかと言いたいと思います。現実には３年前からこの問題は提起されているわけですから、その上での発言をしていますので、その辺のところをご了承ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"この委員会のあり方、持ち様なんですから、皆さんの意見を聞いていただきたい。そういうことも持ち帰っていただいて、どういう方向をこの委員会は持つべきだというのを１回やる方がいいのではないのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"須藤委員長","kind":"提案","question":"委員長としては、今言ったように、必要なことは、もし削減するということであれば、どの定例会で条例提案してくるか。ほかにご発言ございませんか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787035?Template=document&Id=5790#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":62861,"voices":153}},{"id":"h17-20051206-16","meetingId":"h17-cm12","date":"2005年12月6日","dateIso":"2005-12-06","committee":"街づくり特別委員会","time":"午後１時１８分～午後１時５８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"公有地の活用（日野中学校跡地）のまとめ","agenda":"公有地の活用（日野中学校跡地）のまとめ","exchanges":[{"speaker":"山村委員","kind":"意見","question":"前文を見ますと、日野中学校跡地のことだけが書かれていますので、２番とのつながりが薄いと思うんです。第一日野小学校跡地のことが、急に２番で出てくるような感じがしますので、何かしら文章に入れられたほうがいいかなと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"山村委員","kind":"質問","question":"第一日野小学校跡地の問題についても、同時に検討する必要性が生じたため、検討してきた」と。日野中学校跡地と同じようにずっと議論をしてきたわけですから、そのことを載せられたほうがいいんじゃないかなと、私は思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"提案","question":"今の山村委員のご提案ですけれども、「９月２８日の当委員会において、わからないというのは一理あるかなとは思うんです。ＴＯＣのほうも含めてそういう提案があったというふうに変えると、今、聞いていて思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"本多委員","kind":"意見","question":"１番、１番目のことは、地域の拠点としてのことをもとに運営をしてほしいという趣旨の意見を１番に持っていったわけですので。全会派がこういう意見を持っているということはないと思いますので、その取り扱いをどうすればいいかと、ちょっと意見ですとの意見を述べました。","respondent":"宮崎委員長","answer":"そこのところは、正副委員長のほうでも、まとめ方としての考え方ということで理解していただければと思います。最初のほうの、地域の拠点ということは、正副委員長のほうでは、「地域の防災拠点としての機能充実」という表現をさせていただいたんだけれども。","id":"exchange-004"},{"speaker":"本多委員","kind":"意見","question":"１番目のほうの、そういう細かいことも含めて、地域拠点ということを盛り込む。それと同じように、できればその運営についても、地域拠点ということが盛り込めればありがたいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"大沢委員","kind":"提案","question":"文言の整理をしていただくことがどうかということで、よく区で使われます「コミュニティの拠点として機能充実を図っていく」ということを、ご提案申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"三上副委員長","kind":"質問","question":"五反田文化センターについては相当古くなってきているわけですから、将来的には建て直しも十分に考えられる。となれば、あえて屋上屋を重ねるような施設にというところまでは考えなくてもいいんじゃないかと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"その後、そういう背景があったので、委員会として、「緊急かつ効率的な取り組みが強く求められました」と。この時期にまとめて、予算に反映されたいという当委員会の思いもありますので、そこの部分を、少しわかりやすく具体化されればいいかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"第一日野小学校の跡地が出てきているわけですから、３項目の部分的な項目なので、日野中学校跡地の利用計画案で十分だと思います。最初の９月２８日にいただいた資料の意図と、またちょっと変わってくると思いますので、私はこのままでいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"「緊急かつ効率的な取り組みが強く求められました」というところで、特別委員会を開いて、その報告自体は９月２８日になってしまった。どうするかという議論なんですけれども、４年後となると、原小学校のほうが早い時期になりかねないんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"西本委員","kind":"意見","question":"１番目、２番目という形で、議論の流れが書いてありますので、まずは移転ということに対して、それはそれで、皆さんの合意が得られた。いろいろ意見がありましたというような形になっていると思いますので、私は、このままでよろしいのではないかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"本間委員","kind":"提案","question":"出された提案は、第一日野小学校跡地の部分が絡んでいるわけですから、そういうような方法があるのではないかと思います。今まで意見を出し合った中でのまとめとしては、そういう部分も入れておいてもよろしいのではないかという２点を、私どもとして指摘しておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"ここではわからないんですから、きちんとした情報提供なり、議会としての意思をしっかりと示しておく必要があるんじゃないかなと思います。ですから、前文の最後の部分でもいいですから、そこのところは記述をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"中断の７行目ですか、「日野中学校跡地」に、また「と第一日野小学校跡地を含む」とすることは大切なことなのかなと。ですから、せっかく大幅な時間を割いてやってきたわけですから、その辺はちょっとお含みおきいただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"提案","question":"理事者のほうから提案されていたのは、その第一日野小学校の活用ということが一緒に出てきているわけですから。１番と２番という流れになっているわけですから、この原案というのは、大幅に変える必要はないんじゃないかとの意見を述べました。","respondent":"宮崎委員長","answer":"皆さんからいろいろご意見をいただきましたので、それをちょっと今、正副委員長で扱いを検討させていただきました。そうすると、ここを読むと、「地域の防災・コミュニティの拠点として機能充実を図ること」となります。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"すみません、これはもう策定をされて案として出てきているわけですから、意見を取りまとめた」としないとおかしくなるんじゃないでしょうか。それで、２８日の委員会に出てきているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど、委員長が、正副委員長で打ち合わせされて提起してくださったところに、私の意見が入っていなかったので、改めてちょっと。行政のほうとしても受けとめて、今後に生かしていただきたいということを、ちょっと強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664767?Template=document&Id=6316#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":8765,"voices":33}},{"id":"h17-20051208-9","meetingId":"h17-cm12","date":"2005年12月8日","dateIso":"2005-12-08","committee":"文教委員会","time":"午後２時１３分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"第１０７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","agenda":"第１０７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今の説明を伺って、０.９７％というのは、全体を通じてオーバーしているという考え方なんでしょうか。具体的に０.９７％で逆算していけばいいのかわからないんですけれども、民間の存在もちょっと説明を求めました。","respondent":"市川庶務課長","answer":"説明申し上げたように、片や引下げ、片や引上げという改定内容になってあります。この事業所の職種別、規模別の内容については、特に全産業分野にわたって均等に抽出をしていると聞いてあります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"５０人以上それぞれなんですけれども、１００人以上ですから、そういう小さな事業所も含めたトータルのサンプリングということなんですか。５％との関係で、今どういうふうに変化しているかということも含めて、教えてほしいと求めました。","respondent":"市川庶務課長","answer":"あるいは説得力を持った指標というのは、民間給与のほかに見当たらないということで、民間給与との比較を行ってきているものと考えられます。較差がプラスであっても、マイナスであっても、また、その幅がどうであっても、人事委員会としては、その旨、勧告をいたします。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そういう制度の中で行われているところの条例改正ですから、改めて大事なのかということを、ちょっと強く感じております。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"労働市場が流動化しているその問題については、ある程度考慮された上での調査なのか、そこら辺はどうでしょうか。旧態依然とした正社員としてのあれだけなのか、ちょっとわかったら教えてほしいんです。","respondent":"市川庶務課長","answer":"したがって、給与体系ができている事業所を対象に調査をしているということが一つあります。冒頭申し上げたように、今の日本の経済情勢、産業界の動向を極力反映できるような平準化した業種の選定を行っているという説明を受けてあります。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"フランスなんかでは、非常勤の職員、いわゆるパートの人たちを、正社員より１５％高く雇わなきゃならないと法律で決めている。民間の労働者もどんどん下げていくということにつながることを、私はすごく心配をするという意見だけ述べて終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"大沢副委員長","kind":"質問","question":"こういう議案が出てきたわけですけれども、比較をするときに、私立幼稚園との比較はされているんでしょうか。私立幼稚園の先生方の給与体系と、こちらのほうとの比較はされているんか尋ねました。","respondent":"市川庶務課長","answer":"一般に、教育産業はサービス業の位置づけをされていまして、私立の学校、塾といったものがくくられているわけですけれども、ちょっと不明です。","id":"exchange-006"},{"speaker":"大沢副委員長","kind":"質問","question":"幼稚園教育職員の給与に関する条例の一部を改正する条例なんですが、では、ちょっと整理をしますと、幼稚園教育職員の給与に関しては、官と民、いわゆる私立と区立では比較は不明ということで理解していいか尋ねました。","respondent":"市川庶務課長","answer":"その中で、ある特定の業種、私立幼稚園と比較をして、それを個別に反映させるということはやってございません。そのことだけはご理解いただければと思います。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270991?Template=document&Id=4558#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":5654,"voices":21}},{"id":"h17-20051208-5","meetingId":"h17-cm12","date":"2005年12月8日","dateIso":"2005-12-08","committee":"総務委員会","time":"午後２時０９分～午後２時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"第１０６号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第１０６号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"一つは、職員団体との関係をお伺いしたい。それから、４万８,０００円と言われましたけれども、それぞれの額がわかったら、お伺いしたいと思います。","respondent":"桑村人事課長","answer":"一つは、職員団体との関係ですけれども、１１月２１日に職員団体と交渉して、回答をしているものです。基本的に給料表の考え方につきましては、上になればなるほど、高い額になっているものです。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"ここで細かい話じゃないんですけれども、そこら辺のところは、どういうふうに考えているのか。このままいっていいのかと、私は常に思うんですけれども、そこら辺のところは、どういうふうにお考えか尋ねました。","respondent":"桑村人事課長","answer":"いずれにしても、公務員制度そのものが、いわゆる給料決定そのものが、どうして決められないといいますか、そういう考えがあるかと思います。私どもの給料を調査して、その差がどれだけあるかということで判断せざるを得ないのかなと、思っております。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"確認","question":"改定前は７１６万５,０００円という金額が出ていた中で、１日付の広報から出たのは、予算だから数字が違っているのかなという確認。それから、もう一度、区としての支出の総額の確認だけ説明を求めました。","respondent":"桑村人事課長","answer":"一つは、この間、ご報告申し上げましたのは、人事委員会の考え方で、２３区の平均給与ということで考えた数字です。それから、いわゆるマイナスの総額の考え方でよろしいですか。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594587?Template=document&Id=1706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":4004,"voices":20}}]);
